BEGIN;

-- IDs are generated by the application as UUIDv7.

CREATE EXTENSION IF NOT EXISTS btree_gist;

CREATE TABLE tenants (
    id uuid PRIMARY KEY,
    tenant_code varchar(64) NOT NULL UNIQUE,
    tenant_name varchar(200) NOT NULL,
    default_timezone varchar(64) NOT NULL DEFAULT 'Asia/Shanghai',
    default_currency char(3) NOT NULL DEFAULT 'CNY',
    status varchar(24) NOT NULL DEFAULT 'ACTIVE'
        CHECK (status IN ('ACTIVE', 'SUSPENDED', 'CLOSED')),
    settings_json jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    version bigint NOT NULL DEFAULT 0
);

CREATE TABLE currencies (
    code char(3) PRIMARY KEY,
    display_name varchar(100) NOT NULL,
    symbol varchar(16),
    minor_unit smallint NOT NULL CHECK (minor_unit BETWEEN 0 AND 6),
    enabled boolean NOT NULL DEFAULT true,
    created_at timestamptz NOT NULL DEFAULT now()
);

INSERT INTO currencies(code, display_name, symbol, minor_unit) VALUES
('CNY', 'Chinese Yuan', '¥', 2),
('USD', 'US Dollar', '$', 2),
('HKD', 'Hong Kong Dollar', 'HK$', 2),
('JPY', 'Japanese Yen', '¥', 0)
ON CONFLICT (code) DO NOTHING;

ALTER TABLE tenants
    ADD CONSTRAINT fk_tenants_default_currency
    FOREIGN KEY (default_currency) REFERENCES currencies(code);

CREATE TABLE users (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL REFERENCES tenants(id),
    username varchar(100) NOT NULL,
    email varchar(320) NOT NULL,
    display_name varchar(160) NOT NULL,
    password_hash varchar(512),
    mfa_enabled boolean NOT NULL DEFAULT false,
    mfa_secret_ciphertext text,
    mfa_recovery_codes_json jsonb NOT NULL DEFAULT '[]'::jsonb,
    status varchar(24) NOT NULL DEFAULT 'ACTIVE'
        CHECK (status IN ('INVITED', 'ACTIVE', 'LOCKED', 'DISABLED')),
    last_login_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    version bigint NOT NULL DEFAULT 0,
    UNIQUE (tenant_id, username),
    UNIQUE (tenant_id, email),
    UNIQUE (tenant_id, id)
);

CREATE TABLE external_identities (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL REFERENCES tenants(id),
    user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    provider_code varchar(64) NOT NULL,
    subject varchar(320) NOT NULL,
    claims_json jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (tenant_id, provider_code, subject)
);

CREATE TABLE roles (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL REFERENCES tenants(id),
    role_code varchar(100) NOT NULL,
    role_name varchar(160) NOT NULL,
    system_role boolean NOT NULL DEFAULT false,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    version bigint NOT NULL DEFAULT 0,
    UNIQUE (tenant_id, role_code)
);

CREATE TABLE permissions (
    permission_code varchar(160) PRIMARY KEY,
    description varchar(500) NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE role_permissions (
    tenant_id uuid NOT NULL REFERENCES tenants(id),
    role_id uuid NOT NULL REFERENCES roles(id) ON DELETE CASCADE,
    permission_code varchar(160) NOT NULL REFERENCES permissions(permission_code),
    PRIMARY KEY (tenant_id, role_id, permission_code)
);

CREATE TABLE user_roles (
    tenant_id uuid NOT NULL REFERENCES tenants(id),
    user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    role_id uuid NOT NULL REFERENCES roles(id) ON DELETE CASCADE,
    assigned_by uuid REFERENCES users(id),
    assigned_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (tenant_id, user_id, role_id)
);

CREATE TABLE user_sessions (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL REFERENCES tenants(id),
    user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    token_hash varchar(128) NOT NULL UNIQUE,
    ip_address inet,
    user_agent varchar(1000),
    expires_at timestamptz NOT NULL,
    revoked_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX idx_user_sessions_active
    ON user_sessions(user_id, expires_at) WHERE revoked_at IS NULL;

CREATE TABLE spring_session (
    primary_id char(36) PRIMARY KEY,
    session_id char(36) NOT NULL UNIQUE,
    creation_time bigint NOT NULL,
    last_access_time bigint NOT NULL,
    max_inactive_interval integer NOT NULL,
    expiry_time bigint NOT NULL,
    principal_name varchar(100)
);

CREATE INDEX spring_session_ix2 ON spring_session(expiry_time);
CREATE INDEX spring_session_ix3 ON spring_session(principal_name);

CREATE TABLE spring_session_attributes (
    session_primary_id char(36) NOT NULL REFERENCES spring_session(primary_id) ON DELETE CASCADE,
    attribute_name varchar(200) NOT NULL,
    attribute_bytes bytea NOT NULL,
    PRIMARY KEY (session_primary_id, attribute_name)
);

CREATE TABLE files (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL REFERENCES tenants(id),
    storage_provider varchar(24) NOT NULL
        CHECK (storage_provider IN ('MINIO', 'S3', 'LOCAL')),
    bucket_name varchar(160) NOT NULL,
    object_key varchar(1024) NOT NULL,
    original_filename varchar(512) NOT NULL,
    mime_type varchar(255) NOT NULL,
    file_size bigint NOT NULL CHECK (file_size >= 0),
    sha256 char(64) NOT NULL,
    encryption_json jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_by uuid REFERENCES users(id),
    created_at timestamptz NOT NULL DEFAULT now(),
    deleted_at timestamptz,
    UNIQUE (tenant_id, bucket_name, object_key)
);

CREATE INDEX idx_files_sha256 ON files(tenant_id, sha256);

CREATE TABLE customers (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL REFERENCES tenants(id),
    customer_no varchar(64) NOT NULL,
    customer_name varchar(240) NOT NULL,
    customer_type varchar(24) NOT NULL DEFAULT 'ENTERPRISE'
        CHECK (customer_type IN ('ENTERPRISE', 'INDIVIDUAL', 'RESELLER', 'INTERNAL')),
    owner_user_id uuid REFERENCES users(id),
    default_currency char(3) REFERENCES currencies(code),
    default_language varchar(16) NOT NULL DEFAULT 'zh-CN',
    default_billing_cycle varchar(32) NOT NULL DEFAULT 'MONTHLY',
    default_payment_terms_days integer NOT NULL DEFAULT 7 CHECK (default_payment_terms_days >= 0),
    credit_limit_minor bigint,
    status varchar(24) NOT NULL DEFAULT 'ACTIVE'
        CHECK (status IN ('PROSPECT', 'ACTIVE', 'SUSPENDED', 'ARCHIVED')),
    tags_json jsonb NOT NULL DEFAULT '[]'::jsonb,
    notes text,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    version bigint NOT NULL DEFAULT 0,
    UNIQUE (tenant_id, customer_no)
);

CREATE INDEX idx_customers_name ON customers(tenant_id, customer_name);

CREATE TABLE companies (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL REFERENCES tenants(id),
    customer_id uuid NOT NULL REFERENCES customers(id),
    company_code varchar(64) NOT NULL,
    company_name varchar(300) NOT NULL,
    company_name_en varchar(300),
    country_region varchar(100),
    address text,
    tax_number varchar(160),
    invoice_title varchar(300),
    invoice_profile_json jsonb NOT NULL DEFAULT '{}'::jsonb,
    default_currency char(3) REFERENCES currencies(code),
    default_tax_rate numeric(12,8) CHECK (default_tax_rate BETWEEN 0 AND 1),
    status varchar(24) NOT NULL DEFAULT 'ACTIVE'
        CHECK (status IN ('ACTIVE', 'SUSPENDED', 'ARCHIVED')),
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    version bigint NOT NULL DEFAULT 0,
    UNIQUE (tenant_id, company_code)
);

CREATE INDEX idx_companies_customer ON companies(tenant_id, customer_id);

CREATE TABLE customer_contacts (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL REFERENCES tenants(id),
    customer_id uuid NOT NULL REFERENCES customers(id),
    company_id uuid REFERENCES companies(id),
    contact_name varchar(160) NOT NULL,
    contact_type varchar(24) NOT NULL DEFAULT 'GENERAL'
        CHECK (contact_type IN ('GENERAL', 'BUSINESS', 'TECHNICAL', 'FINANCE', 'BILLING')),
    email varchar(320),
    phone varchar(64),
    telegram varchar(160),
    wecom varchar(160),
    language varchar(16),
    receives_invoice boolean NOT NULL DEFAULT false,
    receives_reminder boolean NOT NULL DEFAULT false,
    status varchar(24) NOT NULL DEFAULT 'ACTIVE'
        CHECK (status IN ('ACTIVE', 'INACTIVE')),
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    version bigint NOT NULL DEFAULT 0
);

CREATE TABLE products (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL REFERENCES tenants(id),
    product_code varchar(64) NOT NULL,
    product_name varchar(200) NOT NULL,
    service_type varchar(48) NOT NULL,
    default_unit varchar(48),
    status varchar(24) NOT NULL DEFAULT 'ACTIVE'
        CHECK (status IN ('ACTIVE', 'INACTIVE', 'ARCHIVED')),
    attributes_schema jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    version bigint NOT NULL DEFAULT 0,
    UNIQUE (tenant_id, product_code)
);

CREATE TABLE service_groups (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL REFERENCES tenants(id),
    group_code varchar(64) NOT NULL,
    group_name varchar(200) NOT NULL,
    description text,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    version bigint NOT NULL DEFAULT 0,
    UNIQUE (tenant_id, group_code)
);

CREATE TABLE services (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL REFERENCES tenants(id),
    service_no varchar(80) NOT NULL,
    customer_id uuid NOT NULL REFERENCES customers(id),
    company_id uuid NOT NULL REFERENCES companies(id),
    product_id uuid REFERENCES products(id),
    service_group_id uuid REFERENCES service_groups(id),
    service_name varchar(300) NOT NULL,
    service_type varchar(48) NOT NULL,
    region varchar(120),
    datacenter varchar(160),
    line_name varchar(200),
    activated_on date,
    deactivated_on date,
    status varchar(24) NOT NULL DEFAULT 'PENDING'
        CHECK (status IN ('PENDING', 'ACTIVE', 'SUSPENDED', 'ENDED', 'CANCELLED')),
    attributes_json jsonb NOT NULL DEFAULT '{}'::jsonb,
    notes text,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    version bigint NOT NULL DEFAULT 0,
    CHECK (deactivated_on IS NULL OR activated_on IS NULL OR deactivated_on >= activated_on),
    UNIQUE (tenant_id, service_no)
);

CREATE INDEX idx_services_customer ON services(tenant_id, customer_id, status);
CREATE INDEX idx_services_company ON services(tenant_id, company_id, status);

CREATE TABLE service_resources (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL REFERENCES tenants(id),
    service_id uuid NOT NULL REFERENCES services(id),
    resource_type varchar(32) NOT NULL,
    resource_ref varchar(300) NOT NULL,
    display_name varchar(300),
    attributes_json jsonb NOT NULL DEFAULT '{}'::jsonb,
    effective_from timestamptz,
    effective_to timestamptz,
    status varchar(24) NOT NULL DEFAULT 'ACTIVE'
        CHECK (status IN ('ACTIVE', 'INACTIVE')),
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    version bigint NOT NULL DEFAULT 0,
    CHECK (effective_to IS NULL OR effective_from IS NULL OR effective_to > effective_from),
    UNIQUE (tenant_id, service_id, resource_type, resource_ref)
);

CREATE TABLE contracts (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL REFERENCES tenants(id),
    contract_no varchar(80) NOT NULL,
    customer_id uuid NOT NULL REFERENCES customers(id),
    company_id uuid NOT NULL REFERENCES companies(id),
    contract_name varchar(300) NOT NULL,
    effective_from date NOT NULL,
    effective_to date,
    auto_renew boolean NOT NULL DEFAULT false,
    billing_cycle varchar(32) NOT NULL DEFAULT 'MONTHLY',
    billing_day smallint CHECK (billing_day BETWEEN 1 AND 28),
    payment_terms_days integer NOT NULL DEFAULT 7 CHECK (payment_terms_days >= 0),
    currency_code char(3) NOT NULL REFERENCES currencies(code),
    tax_rate numeric(12,8) CHECK (tax_rate BETWEEN 0 AND 1),
    tax_inclusive boolean NOT NULL DEFAULT false,
    status varchar(24) NOT NULL DEFAULT 'DRAFT'
        CHECK (status IN ('DRAFT', 'PENDING_APPROVAL', 'ACTIVE', 'SUSPENDED', 'EXPIRED', 'TERMINATED', 'VOIDED')),
    notes text,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    version bigint NOT NULL DEFAULT 0,
    CHECK (effective_to IS NULL OR effective_to > effective_from),
    UNIQUE (tenant_id, contract_no)
);

CREATE TABLE contract_files (
    tenant_id uuid NOT NULL REFERENCES tenants(id),
    contract_id uuid NOT NULL REFERENCES contracts(id),
    file_id uuid NOT NULL REFERENCES files(id),
    file_type varchar(32) NOT NULL DEFAULT 'ATTACHMENT',
    created_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (tenant_id, contract_id, file_id)
);

CREATE TABLE pricing_rules (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL REFERENCES tenants(id),
    rule_code varchar(80) NOT NULL,
    rule_name varchar(240) NOT NULL,
    description text,
    status varchar(24) NOT NULL DEFAULT 'ACTIVE'
        CHECK (status IN ('ACTIVE', 'INACTIVE', 'ARCHIVED')),
    current_version_id uuid,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    version bigint NOT NULL DEFAULT 0,
    UNIQUE (tenant_id, rule_code)
);

CREATE TABLE pricing_rule_versions (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL REFERENCES tenants(id),
    pricing_rule_id uuid NOT NULL REFERENCES pricing_rules(id),
    version_no integer NOT NULL CHECK (version_no > 0),
    effective_from timestamptz NOT NULL,
    effective_to timestamptz,
    billing_type varchar(48) NOT NULL,
    currency_code char(3) NOT NULL REFERENCES currencies(code),
    unit varchar(48),
    unit_price numeric(30,12),
    base_fee numeric(30,12),
    committed_quantity numeric(30,12),
    overage_unit_price numeric(30,12),
    minimum_charge numeric(30,12),
    maximum_charge numeric(30,12),
    discount_rate numeric(12,8) CHECK (discount_rate BETWEEN 0 AND 1),
    tax_rate numeric(12,8) CHECK (tax_rate BETWEEN 0 AND 1),
    rounding_mode varchar(32) NOT NULL DEFAULT 'NONE',
    rounding_scale integer,
    config_schema_version integer NOT NULL DEFAULT 1,
    config_json jsonb NOT NULL DEFAULT '{}'::jsonb,
    status varchar(24) NOT NULL DEFAULT 'DRAFT'
        CHECK (status IN ('DRAFT', 'PUBLISHED', 'RETIRED')),
    change_note text,
    created_by uuid REFERENCES users(id),
    created_at timestamptz NOT NULL DEFAULT now(),
    published_at timestamptz,
    CHECK (effective_to IS NULL OR effective_to > effective_from),
    CHECK (maximum_charge IS NULL OR minimum_charge IS NULL OR maximum_charge >= minimum_charge),
    UNIQUE (pricing_rule_id, version_no)
);

CREATE INDEX idx_pricing_versions_effective
    ON pricing_rule_versions(pricing_rule_id, effective_from, effective_to)
    WHERE status = 'PUBLISHED';

ALTER TABLE pricing_rule_versions
    ADD CONSTRAINT uq_pricing_rule_versions_tenant_id_id UNIQUE (tenant_id, id);

ALTER TABLE pricing_rules
    ADD CONSTRAINT fk_pricing_rules_current_version
    FOREIGN KEY (tenant_id, current_version_id)
    REFERENCES pricing_rule_versions(tenant_id, id);

ALTER TABLE pricing_rule_versions
    ADD CONSTRAINT ex_published_pricing_version_period
    EXCLUDE USING gist (
        pricing_rule_id WITH =,
        tstzrange(effective_from, COALESCE(effective_to, 'infinity'::timestamptz), '[)') WITH &&
    ) WHERE (status = 'PUBLISHED')
    DEFERRABLE INITIALLY IMMEDIATE;

CREATE TABLE pricing_tiers (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL REFERENCES tenants(id),
    pricing_rule_version_id uuid NOT NULL REFERENCES pricing_rule_versions(id) ON DELETE CASCADE,
    tier_no integer NOT NULL CHECK (tier_no > 0),
    lower_bound numeric(30,12) NOT NULL,
    upper_bound numeric(30,12),
    unit_price numeric(30,12) NOT NULL,
    pricing_mode varchar(24) NOT NULL CHECK (pricing_mode IN ('GRADUATED', 'VOLUME')),
    CHECK (upper_bound IS NULL OR upper_bound > lower_bound),
    UNIQUE (pricing_rule_version_id, tier_no)
);

CREATE TABLE contract_items (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL REFERENCES tenants(id),
    contract_item_no varchar(100) NOT NULL,
    contract_id uuid NOT NULL REFERENCES contracts(id),
    service_id uuid NOT NULL REFERENCES services(id),
    pricing_rule_id uuid NOT NULL REFERENCES pricing_rules(id),
    item_name varchar(300) NOT NULL,
    billing_type varchar(48) NOT NULL,
    billing_cycle varchar(32) NOT NULL DEFAULT 'MONTHLY',
    effective_from timestamptz NOT NULL,
    effective_to timestamptz,
    default_quantity numeric(30,12),
    unit varchar(48),
    tax_category varchar(64),
    auto_bill boolean NOT NULL DEFAULT true,
    visible_on_invoice boolean NOT NULL DEFAULT true,
    sort_order integer NOT NULL DEFAULT 0,
    status varchar(24) NOT NULL DEFAULT 'DRAFT'
        CHECK (status IN ('DRAFT', 'ACTIVE', 'SUSPENDED', 'ENDED', 'CANCELLED')),
    attributes_json jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    version bigint NOT NULL DEFAULT 0,
    CHECK (effective_to IS NULL OR effective_to > effective_from),
    UNIQUE (tenant_id, contract_item_no)
);

CREATE INDEX idx_contract_items_contract ON contract_items(tenant_id, contract_id, status);
CREATE INDEX idx_contract_items_service ON contract_items(tenant_id, service_id, status);

CREATE TABLE invoice_templates (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL REFERENCES tenants(id),
    template_code varchar(100) NOT NULL,
    template_name varchar(240) NOT NULL,
    template_type varchar(32) NOT NULL DEFAULT 'HTML',
    default_language varchar(16) NOT NULL DEFAULT 'zh-CN',
    status varchar(24) NOT NULL DEFAULT 'DRAFT'
        CHECK (status IN ('DRAFT', 'ACTIVE', 'INACTIVE', 'ARCHIVED')),
    current_version_id uuid,
    created_by uuid REFERENCES users(id),
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    version bigint NOT NULL DEFAULT 0,
    UNIQUE (tenant_id, template_code)
);

CREATE TABLE invoice_template_versions (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL REFERENCES tenants(id),
    template_id uuid NOT NULL REFERENCES invoice_templates(id),
    version_no integer NOT NULL CHECK (version_no > 0),
    html_content text NOT NULL,
    css_content text NOT NULL DEFAULT '',
    schema_json jsonb NOT NULL,
    field_config_json jsonb NOT NULL DEFAULT '{}'::jsonb,
    list_config_json jsonb NOT NULL DEFAULT '[]'::jsonb,
    content_sha256 char(64) NOT NULL,
    change_note text,
    status varchar(24) NOT NULL DEFAULT 'DRAFT'
        CHECK (status IN ('DRAFT', 'PUBLISHED', 'RETIRED')),
    created_by uuid REFERENCES users(id),
    created_at timestamptz NOT NULL DEFAULT now(),
    published_at timestamptz,
    UNIQUE (template_id, version_no)
);

ALTER TABLE invoice_templates
    ADD CONSTRAINT fk_template_current_version
    FOREIGN KEY (current_version_id) REFERENCES invoice_template_versions(id);

CREATE TABLE invoice_template_assets (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL REFERENCES tenants(id),
    template_version_id uuid NOT NULL REFERENCES invoice_template_versions(id) ON DELETE CASCADE,
    asset_key varchar(200) NOT NULL,
    file_id uuid NOT NULL REFERENCES files(id),
    usage_type varchar(32) NOT NULL
        CHECK (usage_type IN ('LOGO', 'IMAGE', 'FONT', 'STAMP', 'OTHER')),
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (template_version_id, asset_key)
);

CREATE TABLE template_bindings (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL REFERENCES tenants(id),
    template_id uuid NOT NULL REFERENCES invoice_templates(id),
    scope_type varchar(32) NOT NULL
        CHECK (scope_type IN ('SYSTEM', 'CUSTOMER', 'COMPANY', 'SERVICE_GROUP', 'SERVICE', 'CONTRACT', 'CONTRACT_ITEM', 'INVOICE_PROFILE')),
    scope_id uuid,
    currency_code char(3) REFERENCES currencies(code),
    language varchar(16),
    priority integer NOT NULL DEFAULT 0,
    status varchar(24) NOT NULL DEFAULT 'ACTIVE'
        CHECK (status IN ('ACTIVE', 'INACTIVE')),
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    version bigint NOT NULL DEFAULT 0,
    UNIQUE NULLS NOT DISTINCT (tenant_id, scope_type, scope_id, currency_code, language, priority)
);

CREATE TABLE approval_workflows (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL REFERENCES tenants(id),
    workflow_code varchar(100) NOT NULL,
    workflow_name varchar(240) NOT NULL,
    status varchar(24) NOT NULL DEFAULT 'ACTIVE'
        CHECK (status IN ('ACTIVE', 'INACTIVE', 'ARCHIVED')),
    current_version_id uuid,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    version bigint NOT NULL DEFAULT 0,
    UNIQUE (tenant_id, workflow_code)
);

CREATE TABLE approval_workflow_versions (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL REFERENCES tenants(id),
    workflow_id uuid NOT NULL REFERENCES approval_workflows(id),
    version_no integer NOT NULL CHECK (version_no > 0),
    conditions_json jsonb NOT NULL DEFAULT '{}'::jsonb,
    status varchar(24) NOT NULL DEFAULT 'DRAFT'
        CHECK (status IN ('DRAFT', 'PUBLISHED', 'RETIRED')),
    created_at timestamptz NOT NULL DEFAULT now(),
    published_at timestamptz,
    UNIQUE (workflow_id, version_no)
);

ALTER TABLE approval_workflows
    ADD CONSTRAINT fk_workflow_current_version
    FOREIGN KEY (current_version_id) REFERENCES approval_workflow_versions(id);

CREATE TABLE approval_steps (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL REFERENCES tenants(id),
    workflow_version_id uuid NOT NULL REFERENCES approval_workflow_versions(id) ON DELETE CASCADE,
    step_no integer NOT NULL CHECK (step_no > 0),
    step_code varchar(100) NOT NULL,
    step_name varchar(200) NOT NULL,
    permission_code varchar(160) REFERENCES permissions(permission_code),
    conditions_json jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (workflow_version_id, step_no),
    UNIQUE (workflow_version_id, step_code)
);

CREATE TABLE invoice_profiles (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL REFERENCES tenants(id),
    profile_code varchar(100) NOT NULL,
    profile_name varchar(240) NOT NULL,
    customer_id uuid NOT NULL REFERENCES customers(id),
    company_id uuid NOT NULL REFERENCES companies(id),
    template_id uuid REFERENCES invoice_templates(id),
    approval_workflow_id uuid REFERENCES approval_workflows(id),
    language varchar(16) NOT NULL DEFAULT 'zh-CN',
    currency_code char(3) NOT NULL REFERENCES currencies(code),
    timezone varchar(64) NOT NULL DEFAULT 'Asia/Shanghai',
    billing_cycle varchar(32) NOT NULL DEFAULT 'MONTHLY',
    billing_day smallint CHECK (billing_day BETWEEN 1 AND 28),
    payment_terms_days integer NOT NULL DEFAULT 7 CHECK (payment_terms_days >= 0),
    tax_calculation_mode varchar(24) NOT NULL DEFAULT 'PER_LINE'
        CHECK (tax_calculation_mode IN ('PER_LINE', 'INVOICE_TOTAL')),
    invoice_number_rule varchar(300) NOT NULL,
    payment_account_json jsonb NOT NULL DEFAULT '{}'::jsonb,
    recipients_json jsonb NOT NULL DEFAULT '[]'::jsonb,
    auto_generate boolean NOT NULL DEFAULT true,
    auto_submit_review boolean NOT NULL DEFAULT false,
    auto_send boolean NOT NULL DEFAULT false,
    status varchar(24) NOT NULL DEFAULT 'DRAFT'
        CHECK (status IN ('DRAFT', 'ACTIVE', 'SUSPENDED', 'ARCHIVED')),
    notes text,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    version bigint NOT NULL DEFAULT 0,
    UNIQUE (tenant_id, profile_code)
);

CREATE TABLE invoice_profile_assignments (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL REFERENCES tenants(id),
    invoice_profile_id uuid NOT NULL REFERENCES invoice_profiles(id) ON DELETE CASCADE,
    contract_item_id uuid NOT NULL REFERENCES contract_items(id),
    assignment_mode varchar(32) NOT NULL DEFAULT 'CHARGE'
        CHECK (assignment_mode IN ('CHARGE', 'ALLOCATE_PERCENT', 'ALLOCATE_FIXED', 'DISPLAY_ONLY')),
    allocation_value numeric(30,12),
    effective_from timestamptz NOT NULL,
    effective_to timestamptz,
    sort_order integer NOT NULL DEFAULT 0,
    reason text,
    status varchar(24) NOT NULL DEFAULT 'ACTIVE'
        CHECK (status IN ('ACTIVE', 'INACTIVE')),
    created_by uuid REFERENCES users(id),
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    version bigint NOT NULL DEFAULT 0,
    CHECK (effective_to IS NULL OR effective_to > effective_from),
    CHECK (
        (assignment_mode IN ('CHARGE', 'DISPLAY_ONLY') AND allocation_value IS NULL)
        OR (assignment_mode = 'ALLOCATE_PERCENT' AND allocation_value > 0 AND allocation_value <= 100)
        OR (assignment_mode = 'ALLOCATE_FIXED' AND allocation_value >= 0)
    )
);

CREATE UNIQUE INDEX uq_active_charge_assignment
    ON invoice_profile_assignments(tenant_id, contract_item_id)
    WHERE assignment_mode = 'CHARGE' AND status = 'ACTIVE' AND effective_to IS NULL;

CREATE TABLE librenms_instances (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL REFERENCES tenants(id),
    instance_code varchar(100) NOT NULL,
    instance_name varchar(240) NOT NULL,
    base_url varchar(1000) NOT NULL,
    api_token_ciphertext text NOT NULL,
    api_version varchar(32),
    timezone varchar(64) NOT NULL,
    connect_timeout_ms integer NOT NULL DEFAULT 5000 CHECK (connect_timeout_ms > 0),
    read_timeout_ms integer NOT NULL DEFAULT 30000 CHECK (read_timeout_ms > 0),
    max_concurrency integer NOT NULL DEFAULT 4 CHECK (max_concurrency BETWEEN 1 AND 100),
    tls_verify boolean NOT NULL DEFAULT true,
    status varchar(24) NOT NULL DEFAULT 'ACTIVE'
        CHECK (status IN ('ACTIVE', 'DISABLED', 'ERROR')),
    last_success_at timestamptz,
    last_failure_at timestamptz,
    consecutive_failures integer NOT NULL DEFAULT 0,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    version bigint NOT NULL DEFAULT 0,
    UNIQUE (tenant_id, instance_code)
);

CREATE TABLE librenms_discovered_bills (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL REFERENCES tenants(id),
    librenms_instance_id uuid NOT NULL REFERENCES librenms_instances(id),
    librenms_bill_id bigint NOT NULL,
    bill_name varchar(500),
    bill_ref varchar(500),
    bill_custid varchar(500),
    bill_type varchar(100),
    bill_state varchar(100),
    source_payload_json jsonb NOT NULL,
    response_hash char(64) NOT NULL,
    discovered_at timestamptz NOT NULL DEFAULT now(),
    last_seen_at timestamptz NOT NULL DEFAULT now(),
    version bigint NOT NULL DEFAULT 0,
    UNIQUE (tenant_id, librenms_instance_id, librenms_bill_id)
);

CREATE INDEX idx_librenms_discovered_bills_lookup
    ON librenms_discovered_bills(tenant_id, librenms_instance_id, bill_name);

CREATE TABLE librenms_bill_mappings (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL REFERENCES tenants(id),
    librenms_instance_id uuid NOT NULL REFERENCES librenms_instances(id),
    librenms_bill_id bigint NOT NULL,
    observed_bill_name varchar(500),
    observed_bill_ref varchar(500),
    observed_bill_custid varchar(500),
    customer_id uuid NOT NULL REFERENCES customers(id),
    company_id uuid NOT NULL REFERENCES companies(id),
    service_id uuid NOT NULL REFERENCES services(id),
    contract_item_id uuid NOT NULL REFERENCES contract_items(id),
    billing_direction varchar(24) NOT NULL DEFAULT 'MAX'
        CHECK (billing_direction IN ('MAX', 'INBOUND', 'OUTBOUND', 'AGGREGATE', 'LIBRENMS_FINAL')),
    source_unit varchar(48),
    effective_from timestamptz NOT NULL,
    effective_to timestamptz,
    discovery_status varchar(24) NOT NULL DEFAULT 'CONFIRMED'
        CHECK (discovery_status IN ('DISCOVERED', 'CONFIRMED', 'REJECTED')),
    status varchar(24) NOT NULL DEFAULT 'ACTIVE'
        CHECK (status IN ('ACTIVE', 'INACTIVE', 'ERROR')),
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    version bigint NOT NULL DEFAULT 0,
    CHECK (effective_to IS NULL OR effective_to > effective_from),
    UNIQUE (tenant_id, librenms_instance_id, librenms_bill_id, effective_from)
);

CREATE UNIQUE INDEX uq_active_mapping_contract_item
    ON librenms_bill_mappings(tenant_id, contract_item_id)
    WHERE status = 'ACTIVE' AND effective_to IS NULL;

CREATE UNIQUE INDEX uq_active_librenms_bill_mapping
    ON librenms_bill_mappings(tenant_id, librenms_instance_id, librenms_bill_id)
    WHERE status = 'ACTIVE' AND effective_to IS NULL;

CREATE TABLE usage_sync_runs (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL REFERENCES tenants(id),
    librenms_instance_id uuid NOT NULL REFERENCES librenms_instances(id),
    mapping_id uuid REFERENCES librenms_bill_mappings(id),
    job_id uuid,
    sync_type varchar(32) NOT NULL
        CHECK (sync_type IN ('DISCOVER', 'CURRENT', 'PERIOD_HISTORY', 'GRAPH', 'VERIFY')),
    period_start timestamptz,
    period_end timestamptz,
    status varchar(24) NOT NULL
        CHECK (status IN ('RUNNING', 'SUCCESS', 'PARTIAL', 'FAILED')),
    request_count integer NOT NULL DEFAULT 0,
    response_hash char(64),
    duration_ms bigint,
    summary_json jsonb NOT NULL DEFAULT '{}'::jsonb,
    error_code varchar(100),
    error_message text,
    started_at timestamptz NOT NULL DEFAULT now(),
    completed_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE usage_current (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL REFERENCES tenants(id),
    mapping_id uuid NOT NULL REFERENCES librenms_bill_mappings(id),
    period_start timestamptz NOT NULL,
    period_end timestamptz NOT NULL,
    rate_95th_in_bps bigint,
    rate_95th_out_bps bigint,
    rate_95th_bps bigint,
    rate_average_bps bigint,
    rate_peak_bps bigint,
    traffic_in_bytes numeric(30,0),
    traffic_out_bytes numeric(30,0),
    traffic_total_bytes numeric(30,0),
    sample_coverage numeric(12,8),
    source_updated_at timestamptz,
    response_hash char(64),
    anomaly_json jsonb NOT NULL DEFAULT '[]'::jsonb,
    updated_at timestamptz NOT NULL DEFAULT now(),
    CHECK (period_end > period_start),
    UNIQUE (tenant_id, mapping_id, period_start, period_end)
);

CREATE TABLE usage_snapshots (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL REFERENCES tenants(id),
    contract_item_id uuid NOT NULL REFERENCES contract_items(id),
    mapping_id uuid REFERENCES librenms_bill_mappings(id),
    librenms_instance_id uuid REFERENCES librenms_instances(id),
    librenms_bill_id bigint,
    bill_hist_id bigint,
    snapshot_kind varchar(24) NOT NULL
        CHECK (snapshot_kind IN ('PREVIEW', 'FINAL', 'MANUAL_CORRECTION')),
    period_start timestamptz NOT NULL,
    period_end timestamptz NOT NULL,
    rate_95th_in_bps bigint,
    rate_95th_out_bps bigint,
    rate_95th_bps bigint,
    rate_average_bps bigint,
    rate_peak_bps bigint,
    traffic_in_bytes numeric(30,0),
    traffic_out_bytes numeric(30,0),
    traffic_total_bytes numeric(30,0),
    billing_direction varchar(24),
    raw_usage numeric(30,12),
    converted_usage numeric(30,12),
    rounded_usage numeric(30,12),
    billing_usage numeric(30,12),
    unit varchar(48),
    sample_coverage numeric(12,8),
    source_timezone varchar(64),
    adapter_version varchar(100),
    data_hash char(64) NOT NULL,
    anomaly_json jsonb NOT NULL DEFAULT '[]'::jsonb,
    invalidated_at timestamptz,
    invalidation_reason text,
    created_by uuid REFERENCES users(id),
    created_at timestamptz NOT NULL DEFAULT now(),
    CHECK (period_end > period_start),
    UNIQUE (tenant_id, contract_item_id, period_start, period_end, snapshot_kind, data_hash)
);

CREATE TABLE usage_snapshot_files (
    tenant_id uuid NOT NULL REFERENCES tenants(id),
    usage_snapshot_id uuid NOT NULL REFERENCES usage_snapshots(id),
    file_id uuid NOT NULL REFERENCES files(id),
    file_role varchar(32) NOT NULL
        CHECK (file_role IN ('RAW_RESPONSE', 'GRAPH_BITS', 'GRAPH_DAY', 'GRAPH_MONTH', 'GRAPHDATA', 'OTHER')),
    created_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (tenant_id, usage_snapshot_id, file_id, file_role)
);

CREATE TABLE invoice_batches (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL REFERENCES tenants(id),
    batch_key varchar(200) NOT NULL,
    batch_name varchar(240) NOT NULL,
    period_start timestamptz NOT NULL,
    period_end timestamptz NOT NULL,
    trigger_type varchar(24) NOT NULL
        CHECK (trigger_type IN ('SCHEDULED', 'MANUAL', 'IMPORT', 'RETRY')),
    status varchar(24) NOT NULL DEFAULT 'PENDING'
        CHECK (status IN ('PENDING', 'RUNNING', 'PARTIAL', 'SUCCESS', 'FAILED', 'CANCELLED')),
    profile_count integer NOT NULL DEFAULT 0 CHECK (profile_count >= 0),
    success_count integer NOT NULL DEFAULT 0 CHECK (success_count >= 0),
    failure_count integer NOT NULL DEFAULT 0 CHECK (failure_count >= 0),
    requested_by uuid REFERENCES users(id),
    started_at timestamptz,
    completed_at timestamptz,
    error_summary_json jsonb NOT NULL DEFAULT '[]'::jsonb,
    created_at timestamptz NOT NULL DEFAULT now(),
    CHECK (period_end > period_start),
    UNIQUE (tenant_id, batch_key)
);

CREATE INDEX idx_invoice_batches_status
    ON invoice_batches(tenant_id, status, created_at DESC);

CREATE TABLE invoice_previews (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL REFERENCES tenants(id),
    preview_number varchar(160) NOT NULL,
    invoice_batch_id uuid REFERENCES invoice_batches(id),
    invoice_profile_id uuid NOT NULL REFERENCES invoice_profiles(id),
    customer_id uuid NOT NULL REFERENCES customers(id),
    company_id uuid NOT NULL REFERENCES companies(id),
    template_id uuid NOT NULL REFERENCES invoice_templates(id),
    template_version_id uuid NOT NULL REFERENCES invoice_template_versions(id),
    approval_workflow_version_id uuid REFERENCES approval_workflow_versions(id),
    origin_invoice_id uuid,
    period_start timestamptz NOT NULL,
    period_end timestamptz NOT NULL,
    issue_date date NOT NULL,
    due_date date NOT NULL,
    timezone varchar(64) NOT NULL,
    language varchar(16) NOT NULL,
    currency_code char(3) NOT NULL REFERENCES currencies(code),
    exchange_rate numeric(30,12) NOT NULL DEFAULT 1 CHECK (exchange_rate > 0),
    subtotal_minor bigint NOT NULL DEFAULT 0,
    discount_minor bigint NOT NULL DEFAULT 0,
    tax_minor bigint NOT NULL DEFAULT 0,
    adjustment_minor bigint NOT NULL DEFAULT 0,
    total_minor bigint NOT NULL DEFAULT 0 CHECK (total_minor >= 0),
    profile_snapshot_json jsonb NOT NULL,
    party_snapshot_json jsonb NOT NULL,
    render_model_json jsonb NOT NULL DEFAULT '{}'::jsonb,
    anomaly_json jsonb NOT NULL DEFAULT '[]'::jsonb,
    calculation_hash char(64),
    status varchar(32) NOT NULL DEFAULT 'GENERATING'
        CHECK (status IN (
            'GENERATING', 'DRAFT', 'BUSINESS_REVIEW', 'FINANCE_REVIEW',
            'APPROVED', 'FINALIZING', 'FINALIZED', 'REJECTED', 'ERROR', 'VOIDED'
        )),
    approval_revision bigint NOT NULL DEFAULT 0 CHECK (approval_revision >= 0),
    generated_at timestamptz,
    approved_at timestamptz,
    finalized_at timestamptz,
    created_by uuid REFERENCES users(id),
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    version bigint NOT NULL DEFAULT 0,
    CHECK (period_end > period_start),
    CHECK (due_date >= issue_date),
    UNIQUE (tenant_id, preview_number)
);

CREATE INDEX idx_invoice_previews_profile_period
    ON invoice_previews(tenant_id, invoice_profile_id, period_start, period_end);

CREATE INDEX idx_invoice_previews_queue
    ON invoice_previews(tenant_id, status, created_at DESC);

CREATE INDEX idx_invoice_previews_customer
    ON invoice_previews(tenant_id, customer_id, company_id, issue_date DESC);

CREATE TABLE invoice_preview_items (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL REFERENCES tenants(id),
    invoice_preview_id uuid NOT NULL REFERENCES invoice_previews(id) ON DELETE CASCADE,
    contract_item_id uuid REFERENCES contract_items(id),
    service_id uuid REFERENCES services(id),
    pricing_rule_version_id uuid REFERENCES pricing_rule_versions(id),
    usage_snapshot_id uuid REFERENCES usage_snapshots(id),
    source_key varchar(300) NOT NULL,
    line_no integer NOT NULL CHECK (line_no > 0),
    item_name varchar(500) NOT NULL,
    item_description text,
    billing_period_start timestamptz NOT NULL,
    billing_period_end timestamptz NOT NULL,
    raw_usage numeric(30,12),
    converted_usage numeric(30,12),
    rounded_usage numeric(30,12),
    billing_usage numeric(30,12),
    quantity numeric(30,12),
    unit varchar(48),
    unit_price numeric(30,12),
    subtotal_minor bigint NOT NULL DEFAULT 0,
    discount_minor bigint NOT NULL DEFAULT 0,
    tax_minor bigint NOT NULL DEFAULT 0,
    total_minor bigint NOT NULL DEFAULT 0,
    calculation_snapshot_json jsonb NOT NULL,
    display_json jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at timestamptz NOT NULL DEFAULT now(),
    CHECK (billing_period_end > billing_period_start),
    UNIQUE (invoice_preview_id, line_no),
    UNIQUE (invoice_preview_id, source_key)
);

CREATE INDEX idx_preview_items_contract_item
    ON invoice_preview_items(tenant_id, contract_item_id, billing_period_start);

CREATE TABLE invoice_preview_adjustments (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL REFERENCES tenants(id),
    invoice_preview_id uuid NOT NULL REFERENCES invoice_previews(id) ON DELETE CASCADE,
    adjustment_type varchar(32) NOT NULL
        CHECK (adjustment_type IN (
            'SURCHARGE', 'DISCOUNT', 'SLA_CREDIT', 'BALANCE_CREDIT', 'CARRY_FORWARD',
            'LATE_FEE', 'PRICE_CORRECTION', 'INSTALLATION', 'TEMP_BANDWIDTH',
            'EXCHANGE_RATE', 'TAX_CORRECTION', 'CUSTOM'
        )),
    description varchar(500) NOT NULL,
    amount_minor bigint NOT NULL,
    tax_rate numeric(12,8) CHECK (tax_rate BETWEEN 0 AND 1),
    included_in_tax_base boolean NOT NULL DEFAULT true,
    reason text NOT NULL,
    attachment_file_id uuid REFERENCES files(id),
    status varchar(24) NOT NULL DEFAULT 'ACTIVE'
        CHECK (status IN ('ACTIVE', 'REMOVED')),
    created_by uuid NOT NULL REFERENCES users(id),
    approved_by uuid REFERENCES users(id),
    created_at timestamptz NOT NULL DEFAULT now(),
    removed_at timestamptz
);

CREATE INDEX idx_preview_adjustments_active
    ON invoice_preview_adjustments(tenant_id, invoice_preview_id, created_at)
    WHERE status = 'ACTIVE';

CREATE TABLE invoice_preview_exclusions (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL REFERENCES tenants(id),
    invoice_preview_id uuid NOT NULL REFERENCES invoice_previews(id) ON DELETE CASCADE,
    invoice_preview_item_id uuid NOT NULL REFERENCES invoice_preview_items(id) ON DELETE CASCADE,
    reason text NOT NULL,
    created_by uuid NOT NULL REFERENCES users(id),
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (invoice_preview_id, invoice_preview_item_id)
);

CREATE TABLE approval_instances (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL REFERENCES tenants(id),
    invoice_preview_id uuid NOT NULL REFERENCES invoice_previews(id) ON DELETE CASCADE,
    workflow_version_id uuid NOT NULL REFERENCES approval_workflow_versions(id),
    preview_version bigint NOT NULL,
    approval_revision bigint NOT NULL,
    status varchar(24) NOT NULL DEFAULT 'PENDING'
        CHECK (status IN ('PENDING', 'APPROVED', 'REJECTED', 'CANCELLED', 'INVALIDATED')),
    current_step_no integer,
    requested_by uuid NOT NULL REFERENCES users(id),
    requested_at timestamptz NOT NULL DEFAULT now(),
    completed_at timestamptz,
    invalidation_reason text,
    UNIQUE (invoice_preview_id, approval_revision)
);

CREATE INDEX idx_approval_instances_pending
    ON approval_instances(tenant_id, status, requested_at)
    WHERE status = 'PENDING';

CREATE TABLE approval_actions (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL REFERENCES tenants(id),
    approval_instance_id uuid NOT NULL REFERENCES approval_instances(id) ON DELETE CASCADE,
    approval_step_id uuid REFERENCES approval_steps(id),
    preview_version bigint NOT NULL,
    action varchar(24) NOT NULL
        CHECK (action IN ('SUBMIT', 'APPROVE', 'REJECT', 'COMMENT', 'CANCEL', 'INVALIDATE')),
    actor_id uuid REFERENCES users(id),
    actor_snapshot_json jsonb NOT NULL DEFAULT '{}'::jsonb,
    comment text,
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX idx_approval_actions_instance
    ON approval_actions(tenant_id, approval_instance_id, created_at);

CREATE TABLE invoices (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL REFERENCES tenants(id),
    invoice_number varchar(180) NOT NULL,
    source_preview_id uuid NOT NULL REFERENCES invoice_previews(id),
    invoice_profile_id uuid NOT NULL REFERENCES invoice_profiles(id),
    customer_id uuid NOT NULL REFERENCES customers(id),
    company_id uuid NOT NULL REFERENCES companies(id),
    template_id uuid NOT NULL REFERENCES invoice_templates(id),
    template_version_id uuid NOT NULL REFERENCES invoice_template_versions(id),
    approval_instance_id uuid NOT NULL REFERENCES approval_instances(id),
    period_start timestamptz NOT NULL,
    period_end timestamptz NOT NULL,
    issue_date date NOT NULL,
    due_date date NOT NULL,
    timezone varchar(64) NOT NULL,
    language varchar(16) NOT NULL,
    currency_code char(3) NOT NULL REFERENCES currencies(code),
    exchange_rate numeric(30,12) NOT NULL DEFAULT 1 CHECK (exchange_rate > 0),
    subtotal_minor bigint NOT NULL,
    discount_minor bigint NOT NULL,
    tax_minor bigint NOT NULL,
    adjustment_minor bigint NOT NULL,
    total_minor bigint NOT NULL CHECK (total_minor >= 0),
    party_snapshot_json jsonb NOT NULL,
    profile_snapshot_json jsonb NOT NULL,
    render_model_json jsonb NOT NULL,
    data_snapshot_hash char(64) NOT NULL,
    document_status varchar(24) NOT NULL DEFAULT 'FINALIZING'
        CHECK (document_status IN ('FINALIZING', 'CONFIRMED', 'SENT', 'VOIDED', 'REPLACED')),
    send_status varchar(24) NOT NULL DEFAULT 'NOT_QUEUED'
        CHECK (send_status IN ('NOT_QUEUED', 'QUEUED', 'PARTIALLY_SENT', 'SENT', 'FAILED')),
    payment_status varchar(24) NOT NULL DEFAULT 'UNPAID'
        CHECK (payment_status IN ('UNPAID', 'PARTIALLY_PAID', 'PAID', 'OVERDUE')),
    finalized_by uuid NOT NULL REFERENCES users(id),
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    confirmed_at timestamptz,
    sent_at timestamptz,
    voided_at timestamptz,
    paid_at timestamptz,
    version bigint NOT NULL DEFAULT 0,
    CHECK (period_end > period_start),
    CHECK (due_date >= issue_date),
    UNIQUE (tenant_id, invoice_number),
    UNIQUE (tenant_id, source_preview_id)
);

ALTER TABLE invoice_previews
    ADD CONSTRAINT fk_preview_origin_invoice
    FOREIGN KEY (origin_invoice_id) REFERENCES invoices(id);

CREATE INDEX idx_invoices_customer_period
    ON invoices(tenant_id, customer_id, company_id, period_start, period_end);

CREATE INDEX idx_invoices_document_queue
    ON invoices(tenant_id, document_status, created_at DESC);

CREATE INDEX idx_invoices_payment_queue
    ON invoices(tenant_id, payment_status, due_date);

CREATE TABLE invoice_items (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL REFERENCES tenants(id),
    invoice_id uuid NOT NULL REFERENCES invoices(id),
    source_preview_item_id uuid REFERENCES invoice_preview_items(id),
    contract_item_id uuid REFERENCES contract_items(id),
    service_id uuid REFERENCES services(id),
    pricing_rule_version_id uuid REFERENCES pricing_rule_versions(id),
    usage_snapshot_id uuid REFERENCES usage_snapshots(id),
    source_key varchar(300) NOT NULL,
    line_no integer NOT NULL CHECK (line_no > 0),
    item_name varchar(500) NOT NULL,
    item_description text,
    billing_period_start timestamptz NOT NULL,
    billing_period_end timestamptz NOT NULL,
    raw_usage numeric(30,12),
    converted_usage numeric(30,12),
    rounded_usage numeric(30,12),
    billing_usage numeric(30,12),
    quantity numeric(30,12),
    unit varchar(48),
    unit_price numeric(30,12),
    subtotal_minor bigint NOT NULL,
    discount_minor bigint NOT NULL,
    tax_minor bigint NOT NULL,
    total_minor bigint NOT NULL,
    calculation_snapshot_json jsonb NOT NULL,
    display_json jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at timestamptz NOT NULL DEFAULT now(),
    CHECK (billing_period_end > billing_period_start),
    UNIQUE (invoice_id, line_no),
    UNIQUE (invoice_id, source_key)
);

CREATE INDEX idx_invoice_items_contract_item
    ON invoice_items(tenant_id, contract_item_id, billing_period_start);

CREATE TABLE invoice_adjustments (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL REFERENCES tenants(id),
    invoice_id uuid NOT NULL REFERENCES invoices(id),
    source_preview_adjustment_id uuid REFERENCES invoice_preview_adjustments(id),
    adjustment_type varchar(32) NOT NULL,
    description varchar(500) NOT NULL,
    amount_minor bigint NOT NULL,
    tax_rate numeric(12,8) CHECK (tax_rate BETWEEN 0 AND 1),
    included_in_tax_base boolean NOT NULL,
    reason text NOT NULL,
    attachment_file_id uuid REFERENCES files(id),
    operator_snapshot_json jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE invoice_files (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL REFERENCES tenants(id),
    invoice_id uuid NOT NULL REFERENCES invoices(id),
    file_id uuid NOT NULL REFERENCES files(id),
    file_role varchar(32) NOT NULL
        CHECK (file_role IN ('PDF', 'RENDER_MODEL', 'HTML_ARCHIVE', 'SUPPORTING_ATTACHMENT')),
    template_version_id uuid REFERENCES invoice_template_versions(id),
    renderer_version varchar(160),
    chromium_version varchar(160),
    font_manifest_json jsonb NOT NULL DEFAULT '[]'::jsonb,
    content_sha256 char(64) NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (invoice_id, file_role, file_id)
);

CREATE INDEX idx_invoice_files_role
    ON invoice_files(tenant_id, invoice_id, file_role);

CREATE TABLE invoice_relations (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL REFERENCES tenants(id),
    source_invoice_id uuid NOT NULL REFERENCES invoices(id),
    target_invoice_id uuid NOT NULL REFERENCES invoices(id),
    relation_type varchar(24) NOT NULL
        CHECK (relation_type IN ('REPLACES', 'CORRECTS', 'VOIDED_BY', 'CREDITED_BY')),
    reason text,
    created_by uuid REFERENCES users(id),
    created_at timestamptz NOT NULL DEFAULT now(),
    CHECK (source_invoice_id <> target_invoice_id),
    UNIQUE (source_invoice_id, target_invoice_id, relation_type)
);

CREATE UNIQUE INDEX uq_invoice_single_replacement
    ON invoice_relations(tenant_id, source_invoice_id)
    WHERE relation_type = 'REPLACES';

CREATE TABLE payments (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL REFERENCES tenants(id),
    payment_number varchar(120) NOT NULL,
    customer_id uuid NOT NULL REFERENCES customers(id),
    company_id uuid REFERENCES companies(id),
    currency_code char(3) NOT NULL REFERENCES currencies(code),
    amount_minor bigint NOT NULL CHECK (amount_minor > 0),
    payment_method varchar(48) NOT NULL,
    source_system varchar(100) NOT NULL DEFAULT 'MANUAL',
    external_reference varchar(300),
    receiving_account_json jsonb NOT NULL DEFAULT '{}'::jsonb,
    payer_snapshot_json jsonb NOT NULL DEFAULT '{}'::jsonb,
    paid_at timestamptz NOT NULL,
    status varchar(32) NOT NULL DEFAULT 'CONFIRMED'
        CHECK (status IN (
            'CONFIRMED', 'PARTIALLY_ALLOCATED', 'ALLOCATED',
            'PARTIALLY_REFUNDED', 'REFUNDED'
        )),
    attachment_file_id uuid REFERENCES files(id),
    notes text,
    created_by uuid REFERENCES users(id),
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    version bigint NOT NULL DEFAULT 0,
    UNIQUE (tenant_id, payment_number)
);

CREATE UNIQUE INDEX uq_payment_external_reference
    ON payments(tenant_id, source_system, external_reference)
    WHERE external_reference IS NOT NULL;

CREATE INDEX idx_payments_customer
    ON payments(tenant_id, customer_id, paid_at DESC);

CREATE TABLE payment_allocations (
    id uuid PRIMARY KEY,
