CREATE OR REPLACE FUNCTION protect_referenced_usage_snapshot()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    IF OLD.snapshot_kind = 'FINAL' THEN
        RAISE EXCEPTION 'final usage snapshot is immutable'
            USING ERRCODE = '55000';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM invoice_items
        WHERE usage_snapshot_id = OLD.id
    ) THEN
        RAISE EXCEPTION 'usage snapshot referenced by a formal invoice is immutable'
            USING ERRCODE = '55000';
    END IF;

    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;

    RETURN NEW;
END;
$$;

CREATE TRIGGER trg_usage_snapshots_protect_formal_reference
BEFORE UPDATE OR DELETE ON usage_snapshots
FOR EACH ROW EXECUTE FUNCTION protect_referenced_usage_snapshot();

-- V14: conserve payment amount across active allocations and confirmed refunds.
DO $$
DECLARE
    invalid_payment_id uuid;
BEGIN
    SELECT payment.id
    INTO invalid_payment_id
    FROM payments payment
    WHERE COALESCE((
              SELECT sum(allocation.amount_minor)
              FROM payment_allocations allocation
              WHERE allocation.tenant_id = payment.tenant_id
                AND allocation.payment_id = payment.id
                AND allocation.status = 'ACTIVE'
          ), 0)
        + COALESCE((
              SELECT sum(refund.amount_minor)
              FROM payment_refunds refund
              WHERE refund.tenant_id = payment.tenant_id
                AND refund.payment_id = payment.id
                AND refund.status = 'CONFIRMED'
          ), 0) > payment.amount_minor
    LIMIT 1;

    IF invalid_payment_id IS NOT NULL THEN
        RAISE EXCEPTION 'Payment % has allocations plus confirmed refunds above its amount', invalid_payment_id
            USING ERRCODE = '23514', CONSTRAINT = 'ck_payment_balance_conserved';
    END IF;
END
$$;

WITH balances AS (
    SELECT payment.id,
           payment.tenant_id,
           payment.amount_minor,
           COALESCE((
               SELECT sum(allocation.amount_minor)
               FROM payment_allocations allocation
               WHERE allocation.tenant_id = payment.tenant_id
                 AND allocation.payment_id = payment.id
                 AND allocation.status = 'ACTIVE'
           ), 0) AS allocated_minor,
           COALESCE((
               SELECT sum(refund.amount_minor)
               FROM payment_refunds refund
               WHERE refund.tenant_id = payment.tenant_id
                 AND refund.payment_id = payment.id
                 AND refund.status = 'CONFIRMED'
           ), 0) AS refunded_minor
    FROM payments payment
    WHERE payment.status IN (
        'CONFIRMED', 'PARTIALLY_ALLOCATED', 'ALLOCATED', 'PARTIALLY_REFUNDED', 'REFUNDED'
    )
), derived AS (
    SELECT id,
           tenant_id,
           CASE
               WHEN refunded_minor = amount_minor THEN 'REFUNDED'
               WHEN refunded_minor > 0 THEN 'PARTIALLY_REFUNDED'
               WHEN allocated_minor = amount_minor THEN 'ALLOCATED'
               WHEN allocated_minor > 0 THEN 'PARTIALLY_ALLOCATED'
               ELSE 'CONFIRMED'
           END AS status
    FROM balances
)
UPDATE payments payment
SET status = derived.status,
    updated_at = now(),
    version = payment.version + 1
FROM derived
WHERE payment.tenant_id = derived.tenant_id
  AND payment.id = derived.id
  AND payment.status IS DISTINCT FROM derived.status;

CREATE OR REPLACE FUNCTION enforce_payment_balance_conservation()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    target_tenant_id uuid;
    target_payment_id uuid;
    payment_amount bigint;
    allocated_amount numeric;
    refunded_amount numeric;
BEGIN
    IF TG_TABLE_NAME = 'payments' THEN
        target_tenant_id := NEW.tenant_id;
        target_payment_id := NEW.id;
    ELSE
        target_tenant_id := NEW.tenant_id;
        target_payment_id := NEW.payment_id;
    END IF;

    SELECT payment.amount_minor
    INTO payment_amount
    FROM payments payment
    WHERE payment.tenant_id = target_tenant_id
      AND payment.id = target_payment_id
    FOR NO KEY UPDATE;

    IF payment_amount IS NULL THEN
        RETURN NEW;
    END IF;

    SELECT COALESCE(sum(allocation.amount_minor), 0)
    INTO allocated_amount
    FROM payment_allocations allocation
    WHERE allocation.tenant_id = target_tenant_id
      AND allocation.payment_id = target_payment_id
      AND allocation.status = 'ACTIVE';

    SELECT COALESCE(sum(refund.amount_minor), 0)
    INTO refunded_amount
    FROM payment_refunds refund
    WHERE refund.tenant_id = target_tenant_id
      AND refund.payment_id = target_payment_id
      AND refund.status = 'CONFIRMED';

    IF allocated_amount + refunded_amount > payment_amount THEN
        RAISE EXCEPTION
            'Payment % balance is not conserved: amount %, allocated %, refunded %',
            target_payment_id, payment_amount, allocated_amount, refunded_amount
            USING ERRCODE = '23514', CONSTRAINT = 'ck_payment_balance_conserved';
    END IF;

    RETURN NEW;
END
$$;

CREATE TRIGGER trg_payment_amount_balance_guard
AFTER UPDATE OF amount_minor ON payments
FOR EACH ROW EXECUTE FUNCTION enforce_payment_balance_conservation();

CREATE TRIGGER trg_payment_allocations_balance_guard
AFTER INSERT OR UPDATE ON payment_allocations
FOR EACH ROW EXECUTE FUNCTION enforce_payment_balance_conservation();

CREATE TRIGGER trg_payment_refunds_balance_guard
AFTER INSERT OR UPDATE ON payment_refunds
FOR EACH ROW EXECUTE FUNCTION enforce_payment_balance_conservation();

-- V15: invalidate stale sessions, bind idempotency to the actor, and persist auth limits.
ALTER TABLE users
    ADD COLUMN security_version bigint NOT NULL DEFAULT 1;

CREATE OR REPLACE FUNCTION bump_user_security_version()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    IF NEW.status IS DISTINCT FROM OLD.status
        OR NEW.password_hash IS DISTINCT FROM OLD.password_hash
        OR NEW.mfa_enabled IS DISTINCT FROM OLD.mfa_enabled THEN
        NEW.security_version := OLD.security_version + 1;
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER trg_users_bump_security_version
BEFORE UPDATE OF status, password_hash, mfa_enabled ON users
FOR EACH ROW EXECUTE FUNCTION bump_user_security_version();

DELETE FROM idempotency_keys;

ALTER TABLE idempotency_keys
    DROP CONSTRAINT IF EXISTS idempotency_keys_tenant_id_idempotency_key_key,
    ADD COLUMN actor_id uuid NOT NULL,
    ADD CONSTRAINT fk_idempotency_keys_actor
        FOREIGN KEY (tenant_id, actor_id) REFERENCES users(tenant_id, id),
    ADD CONSTRAINT uq_idempotency_keys_actor
        UNIQUE (tenant_id, actor_id, idempotency_key);

CREATE TABLE authentication_rate_limits (
    bucket_type varchar(32) NOT NULL
        CHECK (bucket_type IN ('LOGIN_IDENTITY', 'LOGIN_IP', 'MFA_USER', 'MFA_IP')),
    bucket_key_hash char(64) NOT NULL,
    tenant_id uuid REFERENCES tenants(id) ON DELETE CASCADE,
    user_id uuid,
    failure_count integer NOT NULL DEFAULT 0 CHECK (failure_count >= 0),
    window_started_at timestamptz NOT NULL,
    blocked_until timestamptz,
    updated_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (bucket_type, bucket_key_hash),
    CONSTRAINT fk_authentication_rate_limits_user
        FOREIGN KEY (tenant_id, user_id) REFERENCES users(tenant_id, id) ON DELETE CASCADE
);

CREATE INDEX idx_authentication_rate_limits_blocked
    ON authentication_rate_limits(blocked_until)
    WHERE blocked_until IS NOT NULL;

CREATE TABLE mfa_login_challenges (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL,
    user_id uuid NOT NULL,
    session_binding_hash char(64) NOT NULL,
    failed_attempts integer NOT NULL DEFAULT 0 CHECK (failed_attempts BETWEEN 0 AND 5),
    expires_at timestamptz NOT NULL,
    consumed_at timestamptz,
    revoked_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT fk_mfa_login_challenges_user
        FOREIGN KEY (tenant_id, user_id) REFERENCES users(tenant_id, id) ON DELETE CASCADE
);

CREATE UNIQUE INDEX uq_mfa_login_challenges_active_user
    ON mfa_login_challenges(tenant_id, user_id)
    WHERE consumed_at IS NULL AND revoked_at IS NULL;

CREATE INDEX idx_mfa_login_challenges_expiry
    ON mfa_login_challenges(expires_at)
    WHERE consumed_at IS NULL AND revoked_at IS NULL;

-- V16: serialize each tenant's audit chain and make uncertain SMTP outcomes explicit.
CREATE TABLE audit_chain_heads (
    tenant_id uuid PRIMARY KEY REFERENCES tenants(id),
    last_event_hash char(64),
    last_event_id uuid REFERENCES audit_logs(id),
    updated_at timestamptz NOT NULL DEFAULT now()
);

INSERT INTO audit_chain_heads(tenant_id, last_event_hash, last_event_id, updated_at)
SELECT tenant_id, event_hash, id, created_at
FROM (
    SELECT DISTINCT ON (tenant_id) tenant_id, event_hash, id, created_at
    FROM audit_logs
    ORDER BY tenant_id, created_at DESC, id DESC
) latest;

CREATE UNIQUE INDEX uq_audit_logs_previous_hash
    ON audit_logs(tenant_id, previous_hash) NULLS NOT DISTINCT;

ALTER TABLE notification_logs
    ADD COLUMN send_started_at timestamptz;

ALTER TABLE notification_logs
    DROP CONSTRAINT notification_logs_status_check;

ALTER TABLE notification_logs
    ADD CONSTRAINT notification_logs_status_check
    CHECK (status IN (
        'PENDING', 'SENDING', 'SENT', 'RETRY', 'FAILED', 'DEAD', 'CANCELLED', 'UNCERTAIN'
    ));

-- V17: bind MFA enrollment to a reauthenticated session and enforce temporary credentials.
ALTER TABLE users
    ADD COLUMN mfa_last_accepted_counter bigint NOT NULL DEFAULT -1,
    ADD COLUMN must_change_password boolean NOT NULL DEFAULT false,
    ADD COLUMN temporary_password_expires_at timestamptz,
    ADD CONSTRAINT chk_users_mfa_last_accepted_counter
        CHECK (mfa_last_accepted_counter >= -1),
    ADD CONSTRAINT chk_users_temporary_password_state
        CHECK (
            (must_change_password AND temporary_password_expires_at IS NOT NULL)
            OR (NOT must_change_password AND temporary_password_expires_at IS NULL)
        );

DO $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM tenants
        GROUP BY lower(tenant_code)
        HAVING count(*) > 1
    ) OR EXISTS (
        SELECT 1 FROM users
        GROUP BY tenant_id, lower(username)
        HAVING count(*) > 1
    ) OR EXISTS (
        SELECT 1 FROM users
        GROUP BY tenant_id, lower(email)
        HAVING count(*) > 1
    ) THEN
        RAISE EXCEPTION 'V17 cannot enforce case-insensitive login uniqueness: duplicate tenant code, username, or email exists';
    END IF;
END;
$$;

CREATE UNIQUE INDEX uq_tenants_tenant_code_ci
    ON tenants(lower(tenant_code));

CREATE UNIQUE INDEX uq_users_tenant_username_ci
    ON users(tenant_id, lower(username));

CREATE UNIQUE INDEX uq_users_tenant_email_ci
    ON users(tenant_id, lower(email));

CREATE TABLE mfa_enrollment_proofs (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL,
    user_id uuid NOT NULL,
    proof_hash char(64) NOT NULL UNIQUE,
    session_binding_hash char(64) NOT NULL,
    secret_version bigint NOT NULL CHECK (secret_version >= 0),
    expires_at timestamptz NOT NULL,
    consumed_at timestamptz,
    revoked_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT fk_mfa_enrollment_proofs_user
        FOREIGN KEY (tenant_id, user_id) REFERENCES users(tenant_id, id) ON DELETE CASCADE
);

CREATE UNIQUE INDEX uq_mfa_enrollment_proofs_active_user
    ON mfa_enrollment_proofs(tenant_id, user_id)
    WHERE consumed_at IS NULL AND revoked_at IS NULL;

-- Authentication bucket identifiers are now HMAC-SHA256 values derived from the
-- application master key. Pre-V17 raw SHA-256 buckets are transient and incompatible.
DELETE FROM authentication_rate_limits;

CREATE INDEX idx_authentication_rate_limits_cleanup
    ON authentication_rate_limits(updated_at);

CREATE INDEX idx_mfa_login_challenges_cleanup
    ON mfa_login_challenges(updated_at);

CREATE INDEX idx_mfa_enrollment_proofs_cleanup
    ON mfa_enrollment_proofs(updated_at);

DROP TRIGGER trg_users_bump_security_version ON users;

CREATE OR REPLACE FUNCTION bump_user_security_version()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    IF NEW.status IS DISTINCT FROM OLD.status
        OR NEW.password_hash IS DISTINCT FROM OLD.password_hash
        OR NEW.mfa_enabled IS DISTINCT FROM OLD.mfa_enabled
        OR NEW.must_change_password IS DISTINCT FROM OLD.must_change_password
        OR NEW.temporary_password_expires_at IS DISTINCT FROM OLD.temporary_password_expires_at THEN
        NEW.security_version := OLD.security_version + 1;
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER trg_users_bump_security_version
BEFORE UPDATE OF status, password_hash, mfa_enabled, must_change_password, temporary_password_expires_at ON users
FOR EACH ROW EXECUTE FUNCTION bump_user_security_version();

-- V18: validate billing inputs and freeze published/versioned evidence history.
ALTER TABLE pricing_rule_versions
    ADD CONSTRAINT ck_pricing_version_unit_price_nonneg
        CHECK (unit_price IS NULL OR unit_price >= 0) NOT VALID,
    ADD CONSTRAINT ck_pricing_version_base_fee_nonneg
        CHECK (base_fee IS NULL OR base_fee >= 0) NOT VALID,
    ADD CONSTRAINT ck_pricing_version_committed_qty_nonneg
        CHECK (committed_quantity IS NULL OR committed_quantity >= 0) NOT VALID,
    ADD CONSTRAINT ck_pricing_version_overage_price_nonneg
        CHECK (overage_unit_price IS NULL OR overage_unit_price >= 0) NOT VALID,
    ADD CONSTRAINT ck_pricing_version_min_charge_nonneg
        CHECK (minimum_charge IS NULL OR minimum_charge >= 0) NOT VALID,
    ADD CONSTRAINT ck_pricing_version_max_charge_nonneg
        CHECK (maximum_charge IS NULL OR maximum_charge >= 0) NOT VALID,
    ADD CONSTRAINT ck_pricing_version_rounding_mode
        CHECK (rounding_mode IN (
            'NONE', 'DECIMAL_SCALE', 'HALF_UP_INTEGER', 'CEIL_INTEGER', 'CEIL_STEP'
        )) NOT VALID,
    ADD CONSTRAINT ck_pricing_version_rounding_scale
        CHECK (rounding_scale IS NULL OR rounding_scale BETWEEN 0 AND 12) NOT VALID,
    ADD CONSTRAINT ck_pricing_version_decimal_scale_required
        CHECK (rounding_mode <> 'DECIMAL_SCALE' OR rounding_scale IS NOT NULL) NOT VALID;

ALTER TABLE contract_items
    ADD CONSTRAINT ck_contract_items_default_quantity_nonneg
        CHECK (default_quantity IS NULL OR default_quantity >= 0) NOT VALID;

ALTER TABLE pricing_tiers
    ADD CONSTRAINT ck_pricing_tiers_lower_bound_nonneg
        CHECK (lower_bound >= 0) NOT VALID,
    ADD CONSTRAINT ck_pricing_tiers_unit_price_nonneg
        CHECK (unit_price >= 0) NOT VALID;

ALTER TABLE pricing_rule_versions VALIDATE CONSTRAINT ck_pricing_version_unit_price_nonneg;
ALTER TABLE pricing_rule_versions VALIDATE CONSTRAINT ck_pricing_version_base_fee_nonneg;
ALTER TABLE pricing_rule_versions VALIDATE CONSTRAINT ck_pricing_version_committed_qty_nonneg;
ALTER TABLE pricing_rule_versions VALIDATE CONSTRAINT ck_pricing_version_overage_price_nonneg;
ALTER TABLE pricing_rule_versions VALIDATE CONSTRAINT ck_pricing_version_min_charge_nonneg;
ALTER TABLE pricing_rule_versions VALIDATE CONSTRAINT ck_pricing_version_max_charge_nonneg;
ALTER TABLE pricing_rule_versions VALIDATE CONSTRAINT ck_pricing_version_rounding_mode;
ALTER TABLE pricing_rule_versions VALIDATE CONSTRAINT ck_pricing_version_rounding_scale;
ALTER TABLE pricing_rule_versions VALIDATE CONSTRAINT ck_pricing_version_decimal_scale_required;
ALTER TABLE contract_items VALIDATE CONSTRAINT ck_contract_items_default_quantity_nonneg;
ALTER TABLE pricing_tiers VALIDATE CONSTRAINT ck_pricing_tiers_lower_bound_nonneg;
ALTER TABLE pricing_tiers VALIDATE CONSTRAINT ck_pricing_tiers_unit_price_nonneg;

ALTER TABLE payment_allocations
    ADD CONSTRAINT ck_payment_allocations_reversal_state
        CHECK (
            (status = 'ACTIVE' AND reversed_by IS NULL AND reversed_at IS NULL AND reversal_reason IS NULL)
            OR (status = 'REVERSED' AND reversed_by IS NOT NULL AND reversed_at IS NOT NULL
                AND reversal_reason IS NOT NULL AND btrim(reversal_reason) <> '')
        ) NOT VALID;

ALTER TABLE payment_allocations
    VALIDATE CONSTRAINT ck_payment_allocations_reversal_state;

ALTER TABLE payments
    ADD CONSTRAINT ck_payments_status_derived
        CHECK (status IN (
            'CONFIRMED', 'PARTIALLY_ALLOCATED', 'ALLOCATED',
            'PARTIALLY_REFUNDED', 'REFUNDED'
        )) NOT VALID;

ALTER TABLE payments
    VALIDATE CONSTRAINT ck_payments_status_derived;

CREATE OR REPLACE FUNCTION protect_published_version_child()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    child_tenant_id uuid;
    version_id uuid;
    version_status text;
BEGIN
    IF TG_OP IN ('UPDATE', 'DELETE') THEN
        child_tenant_id := (to_jsonb(OLD) ->> 'tenant_id')::uuid;
        version_id := (to_jsonb(OLD) ->> TG_ARGV[1])::uuid;
        EXECUTE format(
            'SELECT status FROM public.%I WHERE tenant_id = $1 AND id = $2 FOR UPDATE',
            TG_ARGV[0]
        ) INTO version_status USING child_tenant_id, version_id;
        IF version_status IN ('PUBLISHED', 'RETIRED') THEN
            RAISE EXCEPTION 'children of published version % in % are immutable', version_id, TG_ARGV[0]
                USING ERRCODE = '55000';
        END IF;
    END IF;

    IF TG_OP IN ('INSERT', 'UPDATE') THEN
        child_tenant_id := (to_jsonb(NEW) ->> 'tenant_id')::uuid;
        version_id := (to_jsonb(NEW) ->> TG_ARGV[1])::uuid;
        EXECUTE format(
            'SELECT status FROM public.%I WHERE tenant_id = $1 AND id = $2 FOR UPDATE',
            TG_ARGV[0]
        ) INTO version_status USING child_tenant_id, version_id;
        IF version_status IN ('PUBLISHED', 'RETIRED') THEN
            RAISE EXCEPTION 'children of published version % in % are immutable', version_id, TG_ARGV[0]
                USING ERRCODE = '55000';
        END IF;
    END IF;

    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER trg_pricing_tiers_protect_published_version
BEFORE INSERT OR UPDATE OR DELETE ON pricing_tiers
FOR EACH ROW EXECUTE FUNCTION protect_published_version_child(
    'pricing_rule_versions', 'pricing_rule_version_id'
);

CREATE TRIGGER trg_template_assets_protect_published_version
BEFORE INSERT OR UPDATE OR DELETE ON invoice_template_assets
FOR EACH ROW EXECUTE FUNCTION protect_published_version_child(
    'invoice_template_versions', 'template_version_id'
);

CREATE TRIGGER trg_approval_steps_protect_published_version
BEFORE INSERT OR UPDATE OR DELETE ON approval_steps
FOR EACH ROW EXECUTE FUNCTION protect_published_version_child(
    'approval_workflow_versions', 'workflow_version_id'
);

CREATE OR REPLACE FUNCTION protect_approval_instance_history()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    allowed_columns text[] := ARRAY[
        'status', 'current_step_no', 'completed_at', 'invalidation_reason'
    ];
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'approval instance history cannot be deleted'
            USING ERRCODE = '55000';
    END IF;

    IF OLD.status <> 'PENDING' THEN
        RAISE EXCEPTION 'completed approval instance is immutable'
            USING ERRCODE = '55000';
    END IF;

    IF (to_jsonb(NEW) - allowed_columns) IS DISTINCT FROM (to_jsonb(OLD) - allowed_columns) THEN
        RAISE EXCEPTION 'approval instance identity and frozen context cannot be changed'
            USING ERRCODE = '55000';
    END IF;

    IF NEW.status = 'PENDING' AND NEW.completed_at IS NOT NULL THEN
        RAISE EXCEPTION 'pending approval instance cannot be completed'
            USING ERRCODE = '23514';
    END IF;

    IF NEW.status <> 'PENDING' AND NEW.completed_at IS NULL THEN
        RAISE EXCEPTION 'terminal approval instance requires completed_at'
            USING ERRCODE = '23514';
    END IF;

    RETURN NEW;
END;
$$;

CREATE TRIGGER trg_approval_instances_protect_history
BEFORE UPDATE OR DELETE ON approval_instances
FOR EACH ROW EXECUTE FUNCTION protect_approval_instance_history();

CREATE TRIGGER trg_approval_actions_append_only
BEFORE UPDATE OR DELETE ON approval_actions
FOR EACH ROW EXECUTE FUNCTION deny_update_or_delete();

CREATE OR REPLACE FUNCTION protect_formal_approval_action_insert()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    PERFORM 1
    FROM approval_instances approval
    WHERE approval.tenant_id = NEW.tenant_id
      AND approval.id = NEW.approval_instance_id
    FOR UPDATE;

    IF EXISTS (
        SELECT 1
        FROM invoices invoice
        WHERE invoice.tenant_id = NEW.tenant_id
          AND invoice.approval_instance_id = NEW.approval_instance_id
    ) THEN
        RAISE EXCEPTION 'formal invoice approval history is frozen'
            USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION lock_approval_history_for_formal_invoice()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    IF NEW.document_status <> 'FINALIZING'
            OR NEW.send_status <> 'NOT_QUEUED'
            OR NEW.payment_status <> 'UNPAID'
            OR NEW.version <> 0
            OR NEW.confirmed_at IS NOT NULL
            OR NEW.sent_at IS NOT NULL
            OR NEW.voided_at IS NOT NULL
            OR NEW.paid_at IS NOT NULL THEN
        RAISE EXCEPTION 'a formal invoice must start in the initial lifecycle state'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_invoices_initial_state';
    END IF;

    PERFORM 1
    FROM approval_instances approval
    WHERE approval.tenant_id = NEW.tenant_id
      AND approval.id = NEW.approval_instance_id
    FOR UPDATE;
    RETURN NEW;
END;
$$;

CREATE TRIGGER trg_invoices_lock_approval_history
BEFORE INSERT ON invoices
FOR EACH ROW EXECUTE FUNCTION lock_approval_history_for_formal_invoice();

CREATE TRIGGER trg_approval_actions_protect_formal_invoice
BEFORE INSERT ON approval_actions
FOR EACH ROW EXECUTE FUNCTION protect_formal_approval_action_insert();

CREATE OR REPLACE FUNCTION public.lock_frozen_file_row(p_tenant_id uuid, p_file_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = pg_catalog, public
AS $$
BEGIN
    IF p_file_id IS NULL THEN
        RETURN;
    END IF;

    PERFORM 1
    FROM public.files file
    WHERE file.tenant_id = p_tenant_id
      AND file.id = p_file_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'file % does not exist in tenant %', p_file_id, p_tenant_id
            USING ERRCODE = '23503';
    END IF;
END;
$$;

CREATE OR REPLACE FUNCTION public.lock_direct_frozen_file_reference()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = pg_catalog, public
AS $$
DECLARE
    target_file_id uuid;
BEGIN
    target_file_id := (to_jsonb(NEW) ->> TG_ARGV[0])::uuid;
    PERFORM public.lock_frozen_file_row(NEW.tenant_id, target_file_id);
    RETURN NEW;
END;
$$;

CREATE TRIGGER trg_invoice_files_lock_file_reference
BEFORE INSERT ON public.invoice_files
FOR EACH ROW EXECUTE FUNCTION public.lock_direct_frozen_file_reference('file_id');

CREATE TRIGGER trg_invoice_adjustments_lock_file_reference
BEFORE INSERT ON public.invoice_adjustments
FOR EACH ROW EXECUTE FUNCTION public.lock_direct_frozen_file_reference('attachment_file_id');

CREATE TRIGGER trg_payments_lock_attachment_file
BEFORE INSERT OR UPDATE OF attachment_file_id ON public.payments
FOR EACH ROW EXECUTE FUNCTION public.lock_direct_frozen_file_reference('attachment_file_id');

-- protect_published_version_child locks the template version first. PostgreSQL runs
-- same-event triggers by name, so the z-prefixed file trigger preserves parent -> file order.
CREATE TRIGGER trg_template_assets_z_lock_file_reference
BEFORE INSERT OR UPDATE ON public.invoice_template_assets
FOR EACH ROW EXECUTE FUNCTION public.lock_direct_frozen_file_reference('file_id');

CREATE OR REPLACE FUNCTION public.lock_template_asset_files_for_freeze()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = pg_catalog, public
AS $$
BEGIN
    IF NEW.status IN ('PUBLISHED', 'RETIRED')
       AND OLD.status NOT IN ('PUBLISHED', 'RETIRED') THEN
        PERFORM file.id
        FROM public.invoice_template_assets asset
        JOIN public.files file
          ON file.tenant_id = asset.tenant_id
         AND file.id = asset.file_id
        WHERE asset.tenant_id = NEW.tenant_id
          AND asset.template_version_id = NEW.id
        ORDER BY file.id
        FOR UPDATE OF file;
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER trg_template_versions_lock_asset_files_for_freeze
BEFORE UPDATE OF status ON public.invoice_template_versions
FOR EACH ROW EXECUTE FUNCTION public.lock_template_asset_files_for_freeze();

CREATE OR REPLACE FUNCTION public.protect_usage_snapshot_file_link()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = pg_catalog, public
AS $$
DECLARE
    old_tenant_id uuid;
    old_snapshot_id uuid;
    old_file_id uuid;
    new_tenant_id uuid;
    new_snapshot_id uuid;
    new_file_id uuid;
    protected boolean;
BEGIN
    IF TG_OP IN ('UPDATE', 'DELETE') THEN
        old_tenant_id := OLD.tenant_id;
        old_snapshot_id := OLD.usage_snapshot_id;
        old_file_id := OLD.file_id;
    END IF;

    IF TG_OP IN ('INSERT', 'UPDATE') THEN
        new_tenant_id := NEW.tenant_id;
        new_snapshot_id := NEW.usage_snapshot_id;
        new_file_id := NEW.file_id;
    END IF;

    PERFORM snapshot.id
    FROM public.usage_snapshots snapshot
    WHERE (old_snapshot_id IS NOT NULL
           AND snapshot.tenant_id = old_tenant_id
           AND snapshot.id = old_snapshot_id)
       OR (new_snapshot_id IS NOT NULL
           AND snapshot.tenant_id = new_tenant_id
           AND snapshot.id = new_snapshot_id)
    ORDER BY snapshot.id, snapshot.tenant_id
    FOR UPDATE OF snapshot;

    PERFORM file.id
    FROM public.files file
    WHERE (old_file_id IS NOT NULL
           AND file.tenant_id = old_tenant_id
           AND file.id = old_file_id)
       OR (new_file_id IS NOT NULL
           AND file.tenant_id = new_tenant_id
           AND file.id = new_file_id)
    ORDER BY file.id, file.tenant_id
    FOR UPDATE OF file;

    IF old_file_id IS NOT NULL AND NOT EXISTS (
        SELECT 1
        FROM public.files file
        WHERE file.tenant_id = old_tenant_id
          AND file.id = old_file_id
    ) THEN
        RAISE EXCEPTION 'file % does not exist in tenant %', old_file_id, old_tenant_id
            USING ERRCODE = '23503';
    END IF;

    IF new_file_id IS NOT NULL AND NOT EXISTS (
        SELECT 1
        FROM public.files file
        WHERE file.tenant_id = new_tenant_id
          AND file.id = new_file_id
    ) THEN
        RAISE EXCEPTION 'file % does not exist in tenant %', new_file_id, new_tenant_id
            USING ERRCODE = '23503';
    END IF;

    IF old_snapshot_id IS NOT NULL THEN
        SELECT snapshot.snapshot_kind = 'FINAL' OR EXISTS (
                   SELECT 1
                   FROM public.invoice_items item
                   WHERE item.tenant_id = snapshot.tenant_id
                     AND item.usage_snapshot_id = snapshot.id
               )
        INTO protected
        FROM public.usage_snapshots snapshot
        WHERE snapshot.tenant_id = old_tenant_id
          AND snapshot.id = old_snapshot_id;
        IF COALESCE(protected, false) THEN
            RAISE EXCEPTION 'formal usage evidence links are immutable'
                USING ERRCODE = '55000';
        END IF;
    END IF;

    IF new_snapshot_id IS NOT NULL THEN
        SELECT snapshot.snapshot_kind = 'FINAL' OR EXISTS (
                   SELECT 1
                   FROM public.invoice_items item
                   WHERE item.tenant_id = snapshot.tenant_id
                     AND item.usage_snapshot_id = snapshot.id
               )
        INTO protected
        FROM public.usage_snapshots snapshot
        WHERE snapshot.tenant_id = new_tenant_id
          AND snapshot.id = new_snapshot_id;
        IF COALESCE(protected, false) THEN
            RAISE EXCEPTION 'formal usage evidence links are immutable'
                USING ERRCODE = '55000';
        END IF;
    END IF;

    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;
    RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.lock_usage_evidence_for_formal_item()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = pg_catalog, public
AS $$
BEGIN
    IF NEW.usage_snapshot_id IS NOT NULL THEN
        PERFORM 1
        FROM public.usage_snapshots snapshot
        WHERE snapshot.tenant_id = NEW.tenant_id
          AND snapshot.id = NEW.usage_snapshot_id
        FOR UPDATE;

        PERFORM file.id
        FROM public.usage_snapshot_files link
        JOIN public.files file
          ON file.tenant_id = link.tenant_id
         AND file.id = link.file_id
        WHERE link.tenant_id = NEW.tenant_id
          AND link.usage_snapshot_id = NEW.usage_snapshot_id
        ORDER BY file.id
        FOR UPDATE OF file;
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER trg_invoice_items_lock_usage_evidence
BEFORE INSERT ON public.invoice_items
FOR EACH ROW EXECUTE FUNCTION public.lock_usage_evidence_for_formal_item();

CREATE TRIGGER trg_usage_snapshot_files_protect_formal_evidence
BEFORE INSERT OR UPDATE OR DELETE ON public.usage_snapshot_files
FOR EACH ROW EXECUTE FUNCTION public.protect_usage_snapshot_file_link();

CREATE OR REPLACE FUNCTION public.lock_usage_files_for_final_transition()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = pg_catalog, public
AS $$
BEGIN
    IF NEW.snapshot_kind = 'FINAL' AND OLD.snapshot_kind <> 'FINAL' THEN
        PERFORM file.id
        FROM public.usage_snapshot_files link
        JOIN public.files file
          ON file.tenant_id = link.tenant_id
         AND file.id = link.file_id
        WHERE link.tenant_id = NEW.tenant_id
          AND link.usage_snapshot_id = NEW.id
        ORDER BY file.id
        FOR UPDATE OF file;
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER trg_usage_snapshots_lock_files_for_final
BEFORE UPDATE OF snapshot_kind ON public.usage_snapshots
FOR EACH ROW EXECUTE FUNCTION public.lock_usage_files_for_final_transition();

CREATE OR REPLACE FUNCTION protect_frozen_file_metadata()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM invoice_files link
        WHERE link.tenant_id = OLD.tenant_id AND link.file_id = OLD.id
    ) OR EXISTS (
        SELECT 1 FROM invoice_adjustments adjustment
        WHERE adjustment.tenant_id = OLD.tenant_id AND adjustment.attachment_file_id = OLD.id
    ) OR EXISTS (
        SELECT 1 FROM payments payment
        WHERE payment.tenant_id = OLD.tenant_id AND payment.attachment_file_id = OLD.id
    ) OR EXISTS (
        SELECT 1
        FROM invoice_template_assets asset
        JOIN invoice_template_versions version
          ON version.tenant_id = asset.tenant_id
         AND version.id = asset.template_version_id
        WHERE asset.tenant_id = OLD.tenant_id
          AND asset.file_id = OLD.id
          AND version.status IN ('PUBLISHED', 'RETIRED')
    ) OR EXISTS (
        SELECT 1
        FROM usage_snapshot_files link
        JOIN usage_snapshots snapshot
          ON snapshot.tenant_id = link.tenant_id
         AND snapshot.id = link.usage_snapshot_id
        WHERE link.tenant_id = OLD.tenant_id
          AND link.file_id = OLD.id
          AND (
              snapshot.snapshot_kind = 'FINAL'
              OR EXISTS (
                  SELECT 1
                  FROM invoice_items item
                  WHERE item.tenant_id = snapshot.tenant_id
                    AND item.usage_snapshot_id = snapshot.id
              )
          )
    ) THEN
        RAISE EXCEPTION 'file metadata referenced by frozen evidence is immutable'
            USING ERRCODE = '55000';
    END IF;

    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER trg_files_protect_frozen_evidence
BEFORE UPDATE OR DELETE ON files
FOR EACH ROW EXECUTE FUNCTION protect_frozen_file_metadata();

CREATE OR REPLACE FUNCTION protect_payment_update()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    allowed_columns text[] := ARRAY['status', 'updated_at', 'version'];
    allocated_minor numeric;
    refunded_minor numeric;
    expected_status text;
BEGIN
    IF (to_jsonb(NEW) - allowed_columns) IS DISTINCT FROM (to_jsonb(OLD) - allowed_columns) THEN
        RAISE EXCEPTION 'payment financial and identity fields are immutable'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_payments_history_immutable';
    END IF;
    IF pg_trigger_depth() <= 1 THEN
        RAISE EXCEPTION 'payment status is derived from active allocations and confirmed refunds'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_payments_status_derived';
    END IF;
    IF NEW.version <> OLD.version + 1 OR NEW.updated_at < OLD.updated_at THEN
        RAISE EXCEPTION 'payment status updates require a monotonic version and timestamp'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_payments_status_update';
    END IF;

    SELECT COALESCE(sum(allocation.amount_minor), 0)
    INTO allocated_minor
    FROM payment_allocations allocation
    WHERE allocation.tenant_id = NEW.tenant_id
      AND allocation.payment_id = NEW.id
      AND allocation.status = 'ACTIVE';

    SELECT COALESCE(sum(refund.amount_minor), 0)
    INTO refunded_minor
    FROM payment_refunds refund
    WHERE refund.tenant_id = NEW.tenant_id
      AND refund.payment_id = NEW.id
      AND refund.status = 'CONFIRMED';

    expected_status := CASE
        WHEN refunded_minor = NEW.amount_minor THEN 'REFUNDED'
        WHEN refunded_minor > 0 THEN 'PARTIALLY_REFUNDED'
        WHEN allocated_minor = NEW.amount_minor THEN 'ALLOCATED'
        WHEN allocated_minor > 0 THEN 'PARTIALLY_ALLOCATED'
        ELSE 'CONFIRMED'
    END;

    IF NEW.status <> expected_status THEN
        RAISE EXCEPTION 'payment status % does not match derived status %', NEW.status, expected_status
            USING ERRCODE = '23514', CONSTRAINT = 'ck_payments_status_derived';
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER trg_payments_protect_history
BEFORE UPDATE ON payments
FOR EACH ROW EXECUTE FUNCTION protect_payment_update();

CREATE OR REPLACE FUNCTION protect_payment_insert()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    IF NEW.status <> 'CONFIRMED' OR NEW.version <> 0 THEN
        RAISE EXCEPTION 'a new payment must start at CONFIRMED with version zero'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_payments_initial_state';
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER trg_payments_protect_initial_state
BEFORE INSERT ON payments
FOR EACH ROW EXECUTE FUNCTION protect_payment_insert();

CREATE OR REPLACE FUNCTION refresh_payment_status_from_history()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    target_tenant_id uuid;
    target_payment_id uuid;
    payment_amount bigint;
    allocated_minor numeric;
    refunded_minor numeric;
    derived_status text;
BEGIN
    IF TG_OP = 'UPDATE' AND NEW.status IS NOT DISTINCT FROM OLD.status THEN
        RETURN NEW;
    END IF;

    target_tenant_id := NEW.tenant_id;
    target_payment_id := NEW.payment_id;

    SELECT payment.amount_minor
    INTO payment_amount
    FROM payments payment
    WHERE payment.tenant_id = target_tenant_id
      AND payment.id = target_payment_id
    FOR NO KEY UPDATE;

    IF payment_amount IS NULL THEN
        RETURN NEW;
    END IF;

    SELECT COALESCE(sum(allocation.amount_minor), 0)
    INTO allocated_minor
    FROM payment_allocations allocation
    WHERE allocation.tenant_id = target_tenant_id
      AND allocation.payment_id = target_payment_id
      AND allocation.status = 'ACTIVE';

    SELECT COALESCE(sum(refund.amount_minor), 0)
    INTO refunded_minor
    FROM payment_refunds refund
    WHERE refund.tenant_id = target_tenant_id
      AND refund.payment_id = target_payment_id
      AND refund.status = 'CONFIRMED';

    derived_status := CASE
        WHEN refunded_minor = payment_amount THEN 'REFUNDED'
        WHEN refunded_minor > 0 THEN 'PARTIALLY_REFUNDED'
        WHEN allocated_minor = payment_amount THEN 'ALLOCATED'
        WHEN allocated_minor > 0 THEN 'PARTIALLY_ALLOCATED'
        ELSE 'CONFIRMED'
    END;

    UPDATE payments
    SET status = derived_status,
        updated_at = clock_timestamp(),
        version = version + 1
    WHERE tenant_id = target_tenant_id
      AND id = target_payment_id;

    RETURN NEW;
END;
$$;

CREATE TRIGGER trg_payment_allocations_refresh_payment_status
AFTER INSERT OR UPDATE ON payment_allocations
FOR EACH ROW EXECUTE FUNCTION refresh_payment_status_from_history();

CREATE TRIGGER trg_payment_refunds_refresh_payment_status
AFTER INSERT OR UPDATE ON payment_refunds
FOR EACH ROW EXECUTE FUNCTION refresh_payment_status_from_history();

CREATE OR REPLACE FUNCTION protect_payment_allocation_update()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    reversal_columns text[] := ARRAY[
        'status', 'reversed_by', 'reversed_at', 'reversal_reason'
    ];
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.status <> 'ACTIVE'
                OR NEW.reversed_by IS NOT NULL
                OR NEW.reversed_at IS NOT NULL
                OR NEW.reversal_reason IS NOT NULL THEN
            RAISE EXCEPTION 'a new payment allocation must start ACTIVE without reversal metadata'
                USING ERRCODE = '23514', CONSTRAINT = 'ck_payment_allocations_initial_state';
        END IF;
        RETURN NEW;
    END IF;

    IF OLD.status <> 'ACTIVE' OR NEW.status <> 'REVERSED' THEN
        RAISE EXCEPTION 'payment allocation only supports ACTIVE to REVERSED'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_payment_allocations_status_transition';
    END IF;
    IF (to_jsonb(NEW) - reversal_columns) IS DISTINCT FROM (to_jsonb(OLD) - reversal_columns) THEN
        RAISE EXCEPTION 'payment allocation financial and identity fields are immutable'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_payment_allocations_history_immutable';
    END IF;
    IF NEW.reversed_by IS NULL OR NEW.reversed_at IS NULL
            OR NEW.reversal_reason IS NULL OR btrim(NEW.reversal_reason) = '' THEN
        RAISE EXCEPTION 'reversed payment allocation requires actor, time, and reason'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_payment_allocations_reversal_state';
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER trg_payment_allocations_protect_history
BEFORE UPDATE ON payment_allocations
FOR EACH ROW EXECUTE FUNCTION protect_payment_allocation_update();

CREATE TRIGGER trg_payment_allocations_protect_initial_state
BEFORE INSERT ON payment_allocations
FOR EACH ROW EXECUTE FUNCTION protect_payment_allocation_update();

CREATE OR REPLACE FUNCTION protect_payment_refund_update()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    IF (to_jsonb(NEW) - 'status') IS DISTINCT FROM (to_jsonb(OLD) - 'status') THEN
        RAISE EXCEPTION 'payment refund financial and identity fields are immutable'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_payment_refunds_history_immutable';
    END IF;
    IF NOT (
        NEW.status = OLD.status
        OR (OLD.status = 'PENDING' AND NEW.status IN ('CONFIRMED', 'FAILED', 'VOIDED'))
        OR (OLD.status = 'CONFIRMED' AND NEW.status = 'VOIDED')
    ) THEN
        RAISE EXCEPTION 'invalid payment refund status transition: % -> %', OLD.status, NEW.status
            USING ERRCODE = '23514', CONSTRAINT = 'ck_payment_refunds_status_transition';
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER trg_payment_refunds_protect_history
BEFORE UPDATE ON payment_refunds
FOR EACH ROW EXECUTE FUNCTION protect_payment_refund_update();

CREATE OR REPLACE FUNCTION deny_delete()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    RAISE EXCEPTION '% history cannot be deleted', TG_TABLE_NAME
        USING ERRCODE = '55000';
END;
$$;

CREATE TRIGGER trg_payments_no_delete
BEFORE DELETE ON payments
FOR EACH ROW EXECUTE FUNCTION deny_delete();

CREATE TRIGGER trg_payment_allocations_no_delete
BEFORE DELETE ON payment_allocations
FOR EACH ROW EXECUTE FUNCTION deny_delete();

CREATE TRIGGER trg_payment_refunds_no_delete
BEFORE DELETE ON payment_refunds
FOR EACH ROW EXECUTE FUNCTION deny_delete();

