-- V27: bind formal invoices to the exact approved preview revision and harden
-- immutable file evidence plus lifecycle timestamp/state integrity.
-- A formal invoice must be an exact frozen copy of the preview revision that
-- was approved immediately before finalization. Lifecycle timestamps and
-- derived states must remain truthful after the invoice is created.

CREATE OR REPLACE FUNCTION public.lock_frozen_file_row(p_tenant_id uuid, p_file_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = pg_catalog, public, pg_temp
AS $$
DECLARE
    target_deleted_at timestamptz;
BEGIN
    IF p_file_id IS NULL THEN
        RETURN;
    END IF;

    SELECT file.deleted_at
    INTO target_deleted_at
    FROM public.files file
    WHERE file.tenant_id = p_tenant_id
      AND file.id = p_file_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'file % does not exist in tenant %', p_file_id, p_tenant_id
            USING ERRCODE = '23503';
    END IF;
    IF target_deleted_at IS NOT NULL THEN
        RAISE EXCEPTION 'deleted file % cannot become immutable evidence', p_file_id
            USING ERRCODE = '23514', CONSTRAINT = 'ck_frozen_file_reference_not_deleted';
    END IF;
END
$$;

CREATE OR REPLACE FUNCTION public.lock_approval_history_for_formal_invoice()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = pg_catalog, public, pg_temp
AS $$
DECLARE
    preview public.invoice_previews%ROWTYPE;
    approval public.approval_instances%ROWTYPE;
BEGIN
    IF NEW.document_status <> 'FINALIZING'
            OR NEW.send_status <> 'NOT_QUEUED'
            OR NEW.payment_status <> 'UNPAID'
            OR NEW.version <> 0
            OR NEW.confirmed_at IS NOT NULL
            OR NEW.sent_at IS NOT NULL
            OR NEW.voided_at IS NOT NULL
            OR NEW.paid_at IS NOT NULL THEN
        RAISE EXCEPTION 'a formal invoice must start in the initial lifecycle state'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_invoices_initial_state';
    END IF;

    SELECT source.*
    INTO preview
    FROM public.invoice_previews source
    WHERE source.tenant_id = NEW.tenant_id
      AND source.id = NEW.source_preview_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'formal invoice source preview does not exist in the tenant'
            USING ERRCODE = '23503', CONSTRAINT = 'fk_invoices_source_preview';
    END IF;

    SELECT source.*
    INTO approval
    FROM public.approval_instances source
    WHERE source.tenant_id = NEW.tenant_id
      AND source.id = NEW.approval_instance_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'formal invoice approval instance does not exist in the tenant'
            USING ERRCODE = '23503', CONSTRAINT = 'fk_invoices_approval_instance';
    END IF;

    IF preview.status <> 'FINALIZING'
            OR preview.approved_at IS NULL
            OR preview.version <= 0
            OR approval.status <> 'APPROVED'
            OR approval.invoice_preview_id IS DISTINCT FROM NEW.source_preview_id
            OR approval.workflow_version_id IS DISTINCT FROM preview.approval_workflow_version_id
            OR approval.preview_version IS DISTINCT FROM preview.version - 1
            OR approval.approval_revision IS DISTINCT FROM preview.approval_revision THEN
        RAISE EXCEPTION 'formal invoice approval does not match the finalized preview revision'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_invoices_approval_binding';
    END IF;

    IF NEW.invoice_profile_id IS DISTINCT FROM preview.invoice_profile_id
            OR NEW.customer_id IS DISTINCT FROM preview.customer_id
            OR NEW.company_id IS DISTINCT FROM preview.company_id
            OR NEW.template_id IS DISTINCT FROM preview.template_id
            OR NEW.template_version_id IS DISTINCT FROM preview.template_version_id
            OR NEW.period_start IS DISTINCT FROM preview.period_start
            OR NEW.period_end IS DISTINCT FROM preview.period_end
            OR NEW.issue_date IS DISTINCT FROM preview.issue_date
            OR NEW.due_date IS DISTINCT FROM preview.due_date
            OR NEW.timezone IS DISTINCT FROM preview.timezone
            OR NEW.language IS DISTINCT FROM preview.language
            OR NEW.currency_code IS DISTINCT FROM preview.currency_code
            OR NEW.exchange_rate IS DISTINCT FROM preview.exchange_rate
            OR NEW.subtotal_minor IS DISTINCT FROM preview.subtotal_minor
            OR NEW.discount_minor IS DISTINCT FROM preview.discount_minor
            OR NEW.tax_minor IS DISTINCT FROM preview.tax_minor
            OR NEW.adjustment_minor IS DISTINCT FROM preview.adjustment_minor
            OR NEW.total_minor IS DISTINCT FROM preview.total_minor
            OR NEW.party_snapshot_json IS DISTINCT FROM preview.party_snapshot_json
            OR NEW.profile_snapshot_json IS DISTINCT FROM preview.profile_snapshot_json
            OR NEW.render_model_json IS DISTINCT FROM preview.render_model_json THEN
        RAISE EXCEPTION 'formal invoice header differs from its approved preview snapshot'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_invoices_preview_snapshot';
    END IF;

    RETURN NEW;
END
$$;

CREATE OR REPLACE FUNCTION public.protect_formal_invoice()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = pg_catalog, public, pg_temp
AS $$
DECLARE
    allowed_columns text[] := ARRAY[
        'document_status', 'send_status', 'payment_status', 'updated_at', 'version',
        'confirmed_at', 'sent_at', 'voided_at', 'paid_at'
    ];
    active_allocated_minor numeric;
    observed_at timestamptz := clock_timestamp();
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'formal invoice cannot be deleted'
            USING ERRCODE = '55000';
    END IF;

    IF (to_jsonb(NEW) - allowed_columns) IS DISTINCT FROM (to_jsonb(OLD) - allowed_columns) THEN
        RAISE EXCEPTION 'frozen invoice fields cannot be changed'
            USING ERRCODE = '55000';
    END IF;

    IF NEW.version <> OLD.version + 1
            OR NEW.updated_at < OLD.updated_at
            OR NEW.updated_at > observed_at THEN
        RAISE EXCEPTION 'formal invoice status updates require a monotonic version and timestamp'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_invoices_status_update';
    END IF;

    IF NEW.document_status <> OLD.document_status AND NOT (
        (OLD.document_status = 'FINALIZING' AND NEW.document_status IN ('CONFIRMED', 'VOIDED'))
        OR (OLD.document_status = 'CONFIRMED' AND NEW.document_status IN ('SENT', 'VOIDED'))
        OR (OLD.document_status = 'SENT' AND NEW.document_status = 'VOIDED')
        OR (OLD.document_status = 'VOIDED' AND NEW.document_status = 'REPLACED')
    ) THEN
        RAISE EXCEPTION 'invalid invoice document status transition: % -> %',
            OLD.document_status, NEW.document_status
            USING ERRCODE = '23514', CONSTRAINT = 'ck_invoices_document_status_transition';
    END IF;

    IF OLD.document_status = 'FINALIZING' AND NEW.document_status = 'CONFIRMED'
            AND NOT EXISTS (
                SELECT 1
                FROM public.invoice_files link
                JOIN public.files file
                  ON file.tenant_id = link.tenant_id
                 AND file.id = link.file_id
                WHERE link.tenant_id = NEW.tenant_id
                  AND link.invoice_id = NEW.id
                  AND link.file_role = 'PDF'
                  AND link.template_version_id = NEW.template_version_id
                  AND link.renderer_version IS NOT NULL
                  AND btrim(link.renderer_version) <> ''
                  AND link.chromium_version IS NOT NULL
                  AND btrim(link.chromium_version) <> ''
                  AND link.content_sha256 = file.sha256
                  AND file.mime_type = 'application/pdf'
                  AND file.file_size > 0
                  AND file.deleted_at IS NULL
            ) THEN
        RAISE EXCEPTION 'formal invoice confirmation requires complete immutable PDF evidence'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_invoices_confirmation_evidence';
    END IF;

    IF OLD.confirmed_at IS NOT NULL
            AND NEW.confirmed_at IS DISTINCT FROM OLD.confirmed_at THEN
        RAISE EXCEPTION 'invoice confirmed_at is immutable once recorded'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_invoices_confirmed_at_immutable';
    END IF;
    IF OLD.confirmed_at IS NULL AND NEW.confirmed_at IS NOT NULL AND NOT (
            OLD.document_status = 'FINALIZING' AND NEW.document_status = 'CONFIRMED') THEN
        RAISE EXCEPTION 'invoice confirmed_at can only be recorded during confirmation'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_invoices_confirmed_at_transition';
    END IF;
    IF (NEW.document_status IN ('CONFIRMED', 'SENT') AND NEW.confirmed_at IS NULL)
            OR (NEW.document_status = 'FINALIZING' AND NEW.confirmed_at IS NOT NULL) THEN
        RAISE EXCEPTION 'invoice confirmed_at is inconsistent with document status'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_invoices_confirmed_at_state';
    END IF;

    IF OLD.sent_at IS NOT NULL AND NEW.sent_at IS DISTINCT FROM OLD.sent_at THEN
        RAISE EXCEPTION 'invoice sent_at is immutable once recorded'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_invoices_sent_at_immutable';
    END IF;
    IF OLD.sent_at IS NULL AND NEW.sent_at IS NOT NULL AND NOT (
            OLD.document_status = 'CONFIRMED'
            AND NEW.document_status = 'SENT'
            AND NEW.send_status IN ('PARTIALLY_SENT', 'SENT')) THEN
        RAISE EXCEPTION 'invoice sent_at can only be recorded with the first successful delivery'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_invoices_sent_at_transition';
    END IF;
    IF NEW.document_status = 'FINALIZING'
            AND (NEW.send_status <> 'NOT_QUEUED' OR NEW.sent_at IS NOT NULL) THEN
        RAISE EXCEPTION 'finalizing invoice cannot enter the notification lifecycle'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_invoices_finalizing_send_state';
    END IF;
    IF NEW.document_status = 'CONFIRMED'
            AND (NEW.send_status IN ('PARTIALLY_SENT', 'SENT') OR NEW.sent_at IS NOT NULL) THEN
        RAISE EXCEPTION 'successful delivery must advance the invoice document status to SENT'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_invoices_confirmed_send_state';
    END IF;
    IF NEW.document_status = 'SENT' AND NEW.sent_at IS NULL THEN
        RAISE EXCEPTION 'sent invoice state requires sent_at'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_invoices_sent_at_state';
    END IF;
    IF (OLD.document_status IN ('VOIDED', 'REPLACED')
            OR (OLD.document_status <> 'VOIDED' AND NEW.document_status = 'VOIDED'))
            AND (NEW.send_status IS DISTINCT FROM OLD.send_status
                OR NEW.sent_at IS DISTINCT FROM OLD.sent_at) THEN
        RAISE EXCEPTION 'terminal invoice transition cannot rewrite delivery history'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_invoices_terminal_send_history';
    END IF;

    IF OLD.voided_at IS NOT NULL AND NEW.voided_at IS DISTINCT FROM OLD.voided_at THEN
        RAISE EXCEPTION 'invoice voided_at is immutable once recorded'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_invoices_voided_at_immutable';
    END IF;
    IF OLD.voided_at IS NULL AND NEW.voided_at IS NOT NULL
            AND NOT (OLD.document_status <> 'VOIDED' AND NEW.document_status = 'VOIDED') THEN
        RAISE EXCEPTION 'invoice voided_at can only be recorded during voiding'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_invoices_voided_at_transition';
    END IF;
    IF (NEW.document_status IN ('VOIDED', 'REPLACED') AND NEW.voided_at IS NULL)
            OR (NEW.document_status NOT IN ('VOIDED', 'REPLACED') AND NEW.voided_at IS NOT NULL) THEN
        RAISE EXCEPTION 'invoice voided_at is inconsistent with document status'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_invoices_voided_at_state';
    END IF;

    IF NEW.confirmed_at IS NOT NULL
            AND (NEW.confirmed_at < NEW.created_at OR NEW.confirmed_at > observed_at) THEN
        RAISE EXCEPTION 'invoice confirmed_at is outside the lifecycle timeline'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_invoices_confirmed_at_timeline';
    END IF;
    IF NEW.sent_at IS NOT NULL
            AND (NEW.confirmed_at IS NULL OR NEW.sent_at < NEW.confirmed_at OR NEW.sent_at > observed_at) THEN
        RAISE EXCEPTION 'invoice sent_at is outside the lifecycle timeline'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_invoices_sent_at_timeline';
    END IF;
    IF NEW.voided_at IS NOT NULL
            AND (NEW.voided_at < COALESCE(NEW.sent_at, NEW.confirmed_at, NEW.created_at)
                OR NEW.voided_at > observed_at) THEN
        RAISE EXCEPTION 'invoice voided_at is outside the lifecycle timeline'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_invoices_voided_at_timeline';
    END IF;

    IF NEW.payment_status IS DISTINCT FROM OLD.payment_status
            OR NEW.paid_at IS DISTINCT FROM OLD.paid_at THEN
        SELECT COALESCE(sum(allocation.amount_minor), 0)
        INTO active_allocated_minor
        FROM public.payment_allocations allocation
        WHERE allocation.tenant_id = NEW.tenant_id
          AND allocation.invoice_id = NEW.id
          AND allocation.status = 'ACTIVE';

        IF (NEW.payment_status = 'UNPAID' AND active_allocated_minor <> 0)
                OR (NEW.payment_status = 'PARTIALLY_PAID'
                    AND NOT (active_allocated_minor > 0 AND active_allocated_minor < NEW.total_minor))
                OR (NEW.payment_status = 'PAID' AND active_allocated_minor <> NEW.total_minor)
                OR (NEW.payment_status = 'OVERDUE' AND NOT (
                    active_allocated_minor < NEW.total_minor
                    AND (observed_at AT TIME ZONE NEW.timezone)::date > NEW.due_date
                )) THEN
            RAISE EXCEPTION 'invoice payment status does not match active payment allocations'
                USING ERRCODE = '23514', CONSTRAINT = 'ck_invoices_payment_status_derived';
        END IF;
    END IF;

    IF (NEW.payment_status = 'PAID' AND NEW.paid_at IS NULL)
            OR (NEW.payment_status <> 'PAID' AND NEW.paid_at IS NOT NULL) THEN
        RAISE EXCEPTION 'invoice paid_at is inconsistent with payment status'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_invoices_paid_at_state';
    END IF;
    IF OLD.payment_status = 'PAID' AND NEW.payment_status = 'PAID'
            AND NEW.paid_at IS DISTINCT FROM OLD.paid_at THEN
        RAISE EXCEPTION 'invoice paid_at is immutable while the invoice remains paid'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_invoices_paid_at_immutable';
    END IF;
    IF NEW.paid_at IS NOT NULL
            AND (NEW.confirmed_at IS NULL OR NEW.paid_at < NEW.confirmed_at OR NEW.paid_at > observed_at) THEN
        RAISE EXCEPTION 'invoice paid_at is outside the lifecycle timeline'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_invoices_paid_at_timeline';
    END IF;

    IF OLD.document_status <> 'VOIDED' AND NEW.document_status = 'VOIDED'
            AND EXISTS (
                SELECT 1
                FROM public.payment_allocations allocation
                WHERE allocation.tenant_id = NEW.tenant_id
                  AND allocation.invoice_id = NEW.id
                  AND allocation.status = 'ACTIVE'
            ) THEN
        RAISE EXCEPTION 'formal invoice with active payment allocations cannot be voided'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_invoices_void_active_payment';
    END IF;

    RETURN NEW;
END
$$;

-- V28: formal line items and adjustments must be exact copies of the approved
-- preview. A correction only replaces its origin after the replacement PDF
-- has been confirmed in the same transaction.

DO $$
BEGIN
    IF EXISTS (
        SELECT 1
        FROM public.invoice_items formal
        JOIN public.invoices invoice
          ON invoice.tenant_id = formal.tenant_id
         AND invoice.id = formal.invoice_id
        LEFT JOIN public.invoice_preview_items source
          ON source.tenant_id = formal.tenant_id
         AND source.id = formal.source_preview_item_id
        LEFT JOIN public.invoice_preview_exclusions exclusion
          ON exclusion.tenant_id = source.tenant_id
         AND exclusion.invoice_preview_id = source.invoice_preview_id
         AND exclusion.invoice_preview_item_id = source.id
        WHERE source.id IS NULL
           OR source.invoice_preview_id IS DISTINCT FROM invoice.source_preview_id
           OR exclusion.id IS NOT NULL
           OR ROW(
                formal.contract_item_id, formal.service_id, formal.pricing_rule_version_id,
                formal.usage_snapshot_id, formal.source_key, formal.line_no,
                formal.item_name, formal.item_description,
                formal.billing_period_start, formal.billing_period_end,
                formal.raw_usage, formal.converted_usage, formal.rounded_usage,
                formal.billing_usage, formal.quantity, formal.unit, formal.unit_price,
                formal.subtotal_minor, formal.discount_minor, formal.tax_minor,
                formal.total_minor, formal.calculation_snapshot_json, formal.display_json
              ) IS DISTINCT FROM ROW(
                source.contract_item_id, source.service_id, source.pricing_rule_version_id,
                source.usage_snapshot_id, source.source_key, source.line_no,
                source.item_name, source.item_description,
                source.billing_period_start, source.billing_period_end,
                source.raw_usage, source.converted_usage, source.rounded_usage,
                source.billing_usage, source.quantity, source.unit, source.unit_price,
                source.subtotal_minor, source.discount_minor, source.tax_minor,
                source.total_minor, source.calculation_snapshot_json, source.display_json
              )
    ) OR EXISTS (
        SELECT 1
        FROM public.invoices invoice
        JOIN public.invoice_preview_items source
          ON source.tenant_id = invoice.tenant_id
         AND source.invoice_preview_id = invoice.source_preview_id
        LEFT JOIN public.invoice_preview_exclusions exclusion
          ON exclusion.tenant_id = source.tenant_id
         AND exclusion.invoice_preview_id = source.invoice_preview_id
         AND exclusion.invoice_preview_item_id = source.id
        LEFT JOIN public.invoice_items formal
          ON formal.tenant_id = invoice.tenant_id
         AND formal.invoice_id = invoice.id
         AND formal.source_preview_item_id = source.id
        WHERE exclusion.id IS NULL
          AND formal.id IS NULL
    ) THEN
        RAISE EXCEPTION 'existing formal invoice items do not exactly match their source previews'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_invoice_items_preview_snapshot';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM public.invoice_adjustments formal
        JOIN public.invoices invoice
          ON invoice.tenant_id = formal.tenant_id
         AND invoice.id = formal.invoice_id
        LEFT JOIN public.invoice_preview_adjustments source
          ON source.tenant_id = formal.tenant_id
         AND source.id = formal.source_preview_adjustment_id
        WHERE source.id IS NULL
           OR source.invoice_preview_id IS DISTINCT FROM invoice.source_preview_id
           OR source.status <> 'ACTIVE'
           OR ROW(
                formal.adjustment_type, formal.description, formal.amount_minor,
                formal.tax_rate, formal.included_in_tax_base, formal.reason,
                formal.attachment_file_id, formal.operator_snapshot_json
              ) IS DISTINCT FROM ROW(
                source.adjustment_type, source.description, source.amount_minor,
                source.tax_rate, source.included_in_tax_base, source.reason,
                source.attachment_file_id,
                jsonb_build_object(
                    'created_by', source.created_by,
                    'approved_by', source.approved_by,
                    'created_at', source.created_at
                )
              )
    ) OR EXISTS (
        SELECT 1
        FROM public.invoices invoice
        JOIN public.invoice_preview_adjustments source
          ON source.tenant_id = invoice.tenant_id
         AND source.invoice_preview_id = invoice.source_preview_id
         AND source.status = 'ACTIVE'
        LEFT JOIN public.invoice_adjustments formal
          ON formal.tenant_id = invoice.tenant_id
         AND formal.invoice_id = invoice.id
         AND formal.source_preview_adjustment_id = source.id
        WHERE formal.id IS NULL
    ) THEN
        RAISE EXCEPTION 'existing formal invoice adjustments do not exactly match their source previews'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_invoice_adjustments_preview_snapshot';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM public.invoice_relations relation
        JOIN public.invoices source
          ON source.tenant_id = relation.tenant_id
         AND source.id = relation.source_invoice_id
        JOIN public.invoices target
          ON target.tenant_id = relation.tenant_id
         AND target.id = relation.target_invoice_id
        JOIN public.invoice_previews preview
          ON preview.tenant_id = target.tenant_id
         AND preview.id = target.source_preview_id
        WHERE relation.relation_type = 'REPLACES'
          AND (source.document_status <> 'REPLACED'
               OR target.document_status = 'FINALIZING'
               OR preview.origin_invoice_id IS DISTINCT FROM source.id)
    ) THEN
        RAISE EXCEPTION 'existing replacement relations are inconsistent with correction lifecycle state'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_invoice_relations_replaces_lifecycle';
    END IF;
END
$$;

ALTER TABLE public.invoice_items
    ALTER COLUMN source_preview_item_id SET NOT NULL;

ALTER TABLE public.invoice_adjustments
    ALTER COLUMN source_preview_adjustment_id SET NOT NULL;

ALTER TABLE public.invoice_items
    ADD CONSTRAINT uq_invoice_items_source_preview
        UNIQUE (invoice_id, source_preview_item_id);

ALTER TABLE public.invoice_adjustments
    ADD CONSTRAINT uq_invoice_adjustments_source_preview
        UNIQUE (invoice_id, source_preview_adjustment_id);

CREATE OR REPLACE FUNCTION public.protect_finalizing_preview_child()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = pg_catalog, public, pg_temp
AS $$
DECLARE
    old_tenant_id uuid;
    old_preview_id uuid;
    new_tenant_id uuid;
    new_preview_id uuid;
    locked_preview record;
BEGIN
    IF TG_OP <> 'INSERT' THEN
        old_tenant_id := OLD.tenant_id;
        old_preview_id := OLD.invoice_preview_id;
    END IF;
    IF TG_OP <> 'DELETE' THEN
        new_tenant_id := NEW.tenant_id;
        new_preview_id := NEW.invoice_preview_id;
    END IF;

    FOR locked_preview IN
        SELECT preview.id, preview.status
        FROM public.invoice_previews preview
        WHERE (old_preview_id IS NOT NULL
               AND preview.tenant_id = old_tenant_id
               AND preview.id = old_preview_id)
           OR (new_preview_id IS NOT NULL
               AND preview.tenant_id = new_tenant_id
               AND preview.id = new_preview_id)
        ORDER BY preview.id
        FOR UPDATE
    LOOP
        IF locked_preview.status IN ('FINALIZING', 'FINALIZED') THEN
            RAISE EXCEPTION 'a finalizing or finalized preview snapshot cannot be changed'
                USING ERRCODE = '55000';
        END IF;
    END LOOP;

    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;
    RETURN NEW;
END
$$;

CREATE OR REPLACE FUNCTION public.validate_formal_invoice_item_insert()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = pg_catalog, public, pg_temp
AS $$
DECLARE
    source_preview_id uuid;
    invoice_status text;
    source public.invoice_preview_items%ROWTYPE;
BEGIN
    IF NEW.source_preview_item_id IS NULL THEN
        RAISE EXCEPTION 'formal invoice item requires a source preview item'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_invoice_items_preview_snapshot';
    END IF;

    SELECT invoice.source_preview_id, invoice.document_status
    INTO source_preview_id, invoice_status
    FROM public.invoices invoice
    WHERE invoice.tenant_id = NEW.tenant_id
      AND invoice.id = NEW.invoice_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'formal invoice item parent does not exist in the tenant'
            USING ERRCODE = '23503';
    END IF;
    IF invoice_status <> 'FINALIZING' THEN
        RAISE EXCEPTION 'formal invoice items can only be inserted while the invoice is finalizing'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_invoice_items_finalizing_insert';
    END IF;

    SELECT item.*
    INTO source
    FROM public.invoice_preview_items item
    WHERE item.tenant_id = NEW.tenant_id
      AND item.id = NEW.source_preview_item_id
    FOR SHARE;
    IF NOT FOUND OR source.invoice_preview_id IS DISTINCT FROM source_preview_id
            OR EXISTS (
                SELECT 1
                FROM public.invoice_preview_exclusions exclusion
                WHERE exclusion.tenant_id = NEW.tenant_id
                  AND exclusion.invoice_preview_id = source_preview_id
                  AND exclusion.invoice_preview_item_id = NEW.source_preview_item_id
            ) THEN
        RAISE EXCEPTION 'formal invoice item source is not an included item of the approved preview'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_invoice_items_preview_source';
    END IF;

    IF ROW(
        NEW.contract_item_id, NEW.service_id, NEW.pricing_rule_version_id,
        NEW.usage_snapshot_id, NEW.source_key, NEW.line_no,
        NEW.item_name, NEW.item_description,
        NEW.billing_period_start, NEW.billing_period_end,
        NEW.raw_usage, NEW.converted_usage, NEW.rounded_usage,
        NEW.billing_usage, NEW.quantity, NEW.unit, NEW.unit_price,
        NEW.subtotal_minor, NEW.discount_minor, NEW.tax_minor,
        NEW.total_minor, NEW.calculation_snapshot_json, NEW.display_json
    ) IS DISTINCT FROM ROW(
        source.contract_item_id, source.service_id, source.pricing_rule_version_id,
        source.usage_snapshot_id, source.source_key, source.line_no,
        source.item_name, source.item_description,
        source.billing_period_start, source.billing_period_end,
        source.raw_usage, source.converted_usage, source.rounded_usage,
        source.billing_usage, source.quantity, source.unit, source.unit_price,
        source.subtotal_minor, source.discount_minor, source.tax_minor,
        source.total_minor, source.calculation_snapshot_json, source.display_json
    ) THEN
        RAISE EXCEPTION 'formal invoice item differs from its approved preview item'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_invoice_items_preview_snapshot';
    END IF;
    RETURN NEW;
END
$$;

CREATE OR REPLACE FUNCTION public.validate_formal_invoice_adjustment_insert()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = pg_catalog, public, pg_temp
AS $$
DECLARE
    source_preview_id uuid;
    invoice_status text;
    source public.invoice_preview_adjustments%ROWTYPE;
    expected_operator_snapshot jsonb;
BEGIN
    IF NEW.source_preview_adjustment_id IS NULL THEN
        RAISE EXCEPTION 'formal invoice adjustment requires a source preview adjustment'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_invoice_adjustments_preview_snapshot';
    END IF;

    SELECT invoice.source_preview_id, invoice.document_status
    INTO source_preview_id, invoice_status
    FROM public.invoices invoice
    WHERE invoice.tenant_id = NEW.tenant_id
      AND invoice.id = NEW.invoice_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'formal invoice adjustment parent does not exist in the tenant'
            USING ERRCODE = '23503';
    END IF;
    IF invoice_status <> 'FINALIZING' THEN
        RAISE EXCEPTION 'formal invoice adjustments can only be inserted while the invoice is finalizing'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_invoice_adjustments_finalizing_insert';
    END IF;

    SELECT adjustment.*
    INTO source
    FROM public.invoice_preview_adjustments adjustment
    WHERE adjustment.tenant_id = NEW.tenant_id
      AND adjustment.id = NEW.source_preview_adjustment_id
    FOR SHARE;
    IF NOT FOUND OR source.invoice_preview_id IS DISTINCT FROM source_preview_id
            OR source.status <> 'ACTIVE' THEN
        RAISE EXCEPTION 'formal invoice adjustment source is not active on the approved preview'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_invoice_adjustments_preview_source';
    END IF;

    expected_operator_snapshot := jsonb_build_object(
        'created_by', source.created_by,
        'approved_by', source.approved_by,
        'created_at', source.created_at
    );
    IF ROW(
        NEW.adjustment_type, NEW.description, NEW.amount_minor, NEW.tax_rate,
        NEW.included_in_tax_base, NEW.reason, NEW.attachment_file_id,
        NEW.operator_snapshot_json
    ) IS DISTINCT FROM ROW(
        source.adjustment_type, source.description, source.amount_minor, source.tax_rate,
        source.included_in_tax_base, source.reason, source.attachment_file_id,
        expected_operator_snapshot
    ) THEN
        RAISE EXCEPTION 'formal invoice adjustment differs from its approved preview adjustment'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_invoice_adjustments_preview_snapshot';
    END IF;
    RETURN NEW;
END
$$;

CREATE OR REPLACE FUNCTION public.validate_invoice_confirmation_and_replacement()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = pg_catalog, public, pg_temp
AS $$
BEGIN
    IF OLD.document_status = 'FINALIZING' AND NEW.document_status = 'CONFIRMED' THEN
        IF EXISTS (
            SELECT 1
            FROM (
                SELECT item.id AS source_id
                FROM public.invoice_preview_items item
                LEFT JOIN public.invoice_preview_exclusions exclusion
                  ON exclusion.tenant_id = item.tenant_id
                 AND exclusion.invoice_preview_id = item.invoice_preview_id
                 AND exclusion.invoice_preview_item_id = item.id
                WHERE item.tenant_id = NEW.tenant_id
                  AND item.invoice_preview_id = NEW.source_preview_id
                  AND exclusion.id IS NULL
                EXCEPT
                SELECT formal.source_preview_item_id
                FROM public.invoice_items formal
                WHERE formal.tenant_id = NEW.tenant_id
                  AND formal.invoice_id = NEW.id
            ) missing_item
        ) OR EXISTS (
            SELECT 1
            FROM (
                SELECT formal.source_preview_item_id AS source_id
                FROM public.invoice_items formal
                WHERE formal.tenant_id = NEW.tenant_id
                  AND formal.invoice_id = NEW.id
                EXCEPT
                SELECT item.id
                FROM public.invoice_preview_items item
                LEFT JOIN public.invoice_preview_exclusions exclusion
                  ON exclusion.tenant_id = item.tenant_id
                 AND exclusion.invoice_preview_id = item.invoice_preview_id
                 AND exclusion.invoice_preview_item_id = item.id
                WHERE item.tenant_id = NEW.tenant_id
                  AND item.invoice_preview_id = NEW.source_preview_id
                  AND exclusion.id IS NULL
            ) extra_item
        ) THEN
            RAISE EXCEPTION 'formal invoice items do not completely cover the approved preview'
                USING ERRCODE = '23514', CONSTRAINT = 'ck_invoice_items_preview_complete';
        END IF;

        IF EXISTS (
            SELECT 1
            FROM (
                SELECT adjustment.id AS source_id
                FROM public.invoice_preview_adjustments adjustment
                WHERE adjustment.tenant_id = NEW.tenant_id
                  AND adjustment.invoice_preview_id = NEW.source_preview_id
                  AND adjustment.status = 'ACTIVE'
                EXCEPT
                SELECT formal.source_preview_adjustment_id
                FROM public.invoice_adjustments formal
                WHERE formal.tenant_id = NEW.tenant_id
                  AND formal.invoice_id = NEW.id
            ) missing_adjustment
        ) OR EXISTS (
            SELECT 1
            FROM (
                SELECT formal.source_preview_adjustment_id AS source_id
                FROM public.invoice_adjustments formal
                WHERE formal.tenant_id = NEW.tenant_id
                  AND formal.invoice_id = NEW.id
                EXCEPT
                SELECT adjustment.id
                FROM public.invoice_preview_adjustments adjustment
                WHERE adjustment.tenant_id = NEW.tenant_id
                  AND adjustment.invoice_preview_id = NEW.source_preview_id
                  AND adjustment.status = 'ACTIVE'
            ) extra_adjustment
        ) THEN
            RAISE EXCEPTION 'formal invoice adjustments do not completely cover the approved preview'
                USING ERRCODE = '23514', CONSTRAINT = 'ck_invoice_adjustments_preview_complete';
        END IF;
    END IF;

    IF OLD.document_status = 'VOIDED' AND NEW.document_status = 'REPLACED'
            AND NOT EXISTS (
                SELECT 1
                FROM public.invoice_relations relation
                JOIN public.invoices target
                  ON target.tenant_id = relation.tenant_id
                 AND target.id = relation.target_invoice_id
                JOIN public.invoice_previews preview
                  ON preview.tenant_id = target.tenant_id
                 AND preview.id = target.source_preview_id
                WHERE relation.tenant_id = NEW.tenant_id
                  AND relation.source_invoice_id = NEW.id
                  AND relation.relation_type = 'REPLACES'
                  AND target.document_status <> 'FINALIZING'
                  AND preview.origin_invoice_id = NEW.id
            ) THEN
        RAISE EXCEPTION 'an invoice can only become replaced through a confirmed correction invoice'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_invoices_replaced_relation';
    END IF;
    RETURN NEW;
END
$$;

CREATE OR REPLACE FUNCTION public.validate_replaces_relation_insert()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = pg_catalog, public, pg_temp
AS $$
DECLARE
    source_status text;
    target_status text;
    target_origin_invoice_id uuid;
BEGIN
    IF NEW.relation_type <> 'REPLACES' THEN
        RETURN NEW;
    END IF;

    PERFORM invoice.id
    FROM public.invoices invoice
    WHERE invoice.tenant_id = NEW.tenant_id
      AND invoice.id IN (NEW.source_invoice_id, NEW.target_invoice_id)
    ORDER BY invoice.id
    FOR UPDATE;

    SELECT source.document_status, target.document_status, preview.origin_invoice_id
    INTO source_status, target_status, target_origin_invoice_id
    FROM public.invoices source
    JOIN public.invoices target
      ON target.tenant_id = source.tenant_id
     AND target.id = NEW.target_invoice_id
    JOIN public.invoice_previews preview
      ON preview.tenant_id = target.tenant_id
     AND preview.id = target.source_preview_id
    WHERE source.tenant_id = NEW.tenant_id
      AND source.id = NEW.source_invoice_id;

    IF NOT FOUND
            OR source_status <> 'VOIDED'
            OR target_status = 'FINALIZING'
            OR target_origin_invoice_id IS DISTINCT FROM NEW.source_invoice_id THEN
        RAISE EXCEPTION 'REPLACES must connect a voided origin to its confirmed correction invoice'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_invoice_relations_replaces_lifecycle';
    END IF;
    RETURN NEW;
END
$$;

CREATE OR REPLACE FUNCTION public.require_completed_correction_replacement()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = pg_catalog, public, pg_temp
AS $$
DECLARE
    origin_invoice_id uuid;
BEGIN
    IF NEW.document_status IS NOT DISTINCT FROM OLD.document_status
            OR NEW.document_status = 'FINALIZING' THEN
        RETURN NULL;
    END IF;

    SELECT preview.origin_invoice_id
    INTO origin_invoice_id
    FROM public.invoice_previews preview
    WHERE preview.tenant_id = NEW.tenant_id
      AND preview.id = NEW.source_preview_id;
    IF origin_invoice_id IS NULL THEN
        RETURN NULL;
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM public.invoice_relations relation
        JOIN public.invoices origin
          ON origin.tenant_id = relation.tenant_id
         AND origin.id = relation.source_invoice_id
        WHERE relation.tenant_id = NEW.tenant_id
          AND relation.source_invoice_id = origin_invoice_id
          AND relation.target_invoice_id = NEW.id
          AND relation.relation_type = 'REPLACES'
          AND origin.document_status = 'REPLACED'
    ) THEN
        RAISE EXCEPTION 'confirmed correction invoice requires a completed replacement relation'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_invoices_correction_replacement_complete';
    END IF;
    RETURN NULL;
END
$$;

CREATE TRIGGER trg_preview_items_protect_final_snapshot
BEFORE INSERT OR UPDATE OR DELETE ON public.invoice_preview_items
FOR EACH ROW EXECUTE FUNCTION public.protect_finalizing_preview_child();

CREATE TRIGGER trg_preview_adjustments_protect_final_snapshot
BEFORE INSERT OR UPDATE OR DELETE ON public.invoice_preview_adjustments
FOR EACH ROW EXECUTE FUNCTION public.protect_finalizing_preview_child();

CREATE TRIGGER trg_preview_exclusions_protect_final_snapshot
BEFORE INSERT OR UPDATE OR DELETE ON public.invoice_preview_exclusions
FOR EACH ROW EXECUTE FUNCTION public.protect_finalizing_preview_child();

CREATE TRIGGER trg_invoice_items_check_preview_snapshot
BEFORE INSERT ON public.invoice_items
FOR EACH ROW EXECUTE FUNCTION public.validate_formal_invoice_item_insert();

CREATE TRIGGER trg_invoice_adjustments_check_preview_snapshot
BEFORE INSERT ON public.invoice_adjustments
FOR EACH ROW EXECUTE FUNCTION public.validate_formal_invoice_adjustment_insert();

CREATE TRIGGER trg_invoices_validate_confirmation_and_replacement
BEFORE UPDATE OF document_status ON public.invoices
FOR EACH ROW EXECUTE FUNCTION public.validate_invoice_confirmation_and_replacement();

CREATE TRIGGER trg_invoice_relations_validate_replaces
BEFORE INSERT ON public.invoice_relations
FOR EACH ROW EXECUTE FUNCTION public.validate_replaces_relation_insert();

CREATE CONSTRAINT TRIGGER trg_invoices_require_completed_correction
AFTER UPDATE ON public.invoices
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION public.require_completed_correction_replacement();

-- V29: payment allocations are the source of truth for both payment and
-- invoice status. Refresh the invoice in the same trigger transaction so
-- direct SQL cannot leave invoices permanently stale.

CREATE OR REPLACE FUNCTION public.refresh_payment_status_from_history()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = pg_catalog, public, pg_temp
AS $$
DECLARE
    target_tenant_id uuid;
    target_payment_id uuid;
    target_invoice_id uuid;
    payment_amount bigint;
    allocated_minor numeric;
    refunded_minor numeric;
    derived_status text;
    invoice_total_minor bigint;
    invoice_due_date date;
    invoice_timezone text;
    invoice_document_status text;
    invoice_allocated_minor numeric;
    invoice_status text;
    invoice_paid_at timestamptz;
    derived_invoice_status text;
    derived_invoice_paid_at timestamptz;
BEGIN
    IF TG_OP = 'UPDATE' AND NEW.status IS NOT DISTINCT FROM OLD.status THEN
        RETURN NEW;
    END IF;

    target_tenant_id := NEW.tenant_id;
    target_payment_id := NEW.payment_id;
    IF TG_TABLE_NAME = 'payment_allocations' THEN
        target_invoice_id := NEW.invoice_id;
    END IF;

    SELECT payment.amount_minor
    INTO payment_amount
    FROM public.payments payment
    WHERE payment.tenant_id = target_tenant_id
      AND payment.id = target_payment_id
    FOR NO KEY UPDATE;

    IF payment_amount IS NULL THEN
        RETURN NEW;
    END IF;

    SELECT COALESCE(sum(allocation.amount_minor), 0)
    INTO allocated_minor
    FROM public.payment_allocations allocation
    WHERE allocation.tenant_id = target_tenant_id
      AND allocation.payment_id = target_payment_id
      AND allocation.status = 'ACTIVE';

    SELECT COALESCE(sum(refund.amount_minor), 0)
    INTO refunded_minor
    FROM public.payment_refunds refund
    WHERE refund.tenant_id = target_tenant_id
      AND refund.payment_id = target_payment_id
      AND refund.status = 'CONFIRMED';

    derived_status := CASE
        WHEN refunded_minor = payment_amount THEN 'REFUNDED'
        WHEN refunded_minor > 0 THEN 'PARTIALLY_REFUNDED'
        WHEN allocated_minor = payment_amount THEN 'ALLOCATED'
        WHEN allocated_minor > 0 THEN 'PARTIALLY_ALLOCATED'
        ELSE 'CONFIRMED'
    END;

    UPDATE public.payments
    SET status = derived_status,
        updated_at = clock_timestamp(),
        version = version + 1
    WHERE tenant_id = target_tenant_id
      AND id = target_payment_id;

    IF target_invoice_id IS NULL THEN
        RETURN NEW;
    END IF;

    SELECT invoice.total_minor, invoice.due_date, invoice.timezone,
           invoice.document_status, invoice.payment_status, invoice.paid_at
    INTO invoice_total_minor, invoice_due_date, invoice_timezone,
         invoice_document_status, invoice_status, invoice_paid_at
    FROM public.invoices invoice
    WHERE invoice.tenant_id = target_tenant_id
      AND invoice.id = target_invoice_id
    FOR NO KEY UPDATE;

    IF invoice_total_minor IS NULL THEN
        RETURN NEW;
    END IF;

    SELECT COALESCE(sum(allocation.amount_minor), 0)
    INTO invoice_allocated_minor
    FROM public.payment_allocations allocation
    WHERE allocation.tenant_id = target_tenant_id
      AND allocation.invoice_id = target_invoice_id
      AND allocation.status = 'ACTIVE';

    IF invoice_allocated_minor > invoice_total_minor THEN
        RAISE EXCEPTION 'payment allocations exceed invoice total'
            USING ERRCODE = '23514', CONSTRAINT = 'ck_payment_allocations_invoice_outstanding';
    END IF;

    derived_invoice_status := CASE
        WHEN invoice_allocated_minor = invoice_total_minor THEN 'PAID'
        WHEN (clock_timestamp() AT TIME ZONE invoice_timezone)::date > invoice_due_date THEN 'OVERDUE'
        WHEN invoice_allocated_minor > 0 THEN 'PARTIALLY_PAID'
        ELSE 'UNPAID'
    END;
    derived_invoice_paid_at := CASE
        WHEN derived_invoice_status = 'PAID' THEN COALESCE(invoice_paid_at, clock_timestamp())
        ELSE NULL
    END;

    UPDATE public.invoices
    SET payment_status = derived_invoice_status,
        paid_at = derived_invoice_paid_at,
        updated_at = clock_timestamp(),
        version = version + 1
    WHERE tenant_id = target_tenant_id
      AND id = target_invoice_id;

    RETURN NEW;
END
$$;

WITH invoice_balances AS (
    SELECT invoice.id,
           invoice.tenant_id,
           invoice.total_minor,
           invoice.due_date,
           invoice.timezone,
           invoice.document_status,
           invoice.payment_status,
           invoice.paid_at,
           COALESCE(sum(allocation.amount_minor)
                    FILTER (WHERE allocation.status = 'ACTIVE'), 0) AS allocated_minor
    FROM public.invoices invoice
    LEFT JOIN public.payment_allocations allocation
      ON allocation.tenant_id = invoice.tenant_id
     AND allocation.invoice_id = invoice.id
    GROUP BY invoice.id
), derived AS (
    SELECT balance.*,
           CASE
               WHEN balance.document_status NOT IN ('CONFIRMED', 'SENT') THEN 'UNPAID'
               WHEN balance.allocated_minor = balance.total_minor THEN 'PAID'
               WHEN (clock_timestamp() AT TIME ZONE balance.timezone)::date > balance.due_date THEN 'OVERDUE'
               WHEN balance.allocated_minor > 0 THEN 'PARTIALLY_PAID'
               ELSE 'UNPAID'
           END AS derived_status
    FROM invoice_balances balance
)
UPDATE public.invoices invoice
SET payment_status = derived.derived_status,
    paid_at = CASE
        WHEN derived.derived_status = 'PAID' THEN COALESCE(invoice.paid_at, clock_timestamp())
        ELSE NULL
    END,
    updated_at = clock_timestamp(),
    version = invoice.version + 1
FROM derived
WHERE invoice.tenant_id = derived.tenant_id
  AND invoice.id = derived.id
  AND (invoice.payment_status IS DISTINCT FROM derived.derived_status
       OR (derived.derived_status = 'PAID' AND invoice.paid_at IS NULL)
       OR (derived.derived_status <> 'PAID' AND invoice.paid_at IS NOT NULL));

COMMIT;
